    // ── §12 paint gate: publish_render_state's off-keystroke paint
    //    decision (lsp-architecture.md §12) ──────────────────────────
    //
    // The cells / virtual-rows workers fire `paint_request` only when
    // THEIR content changes. A change confined to a non-cell surface
    // (modeline badge, diagnostics overlay, minibuffer, popup, cursor …)
    // would land in `RenderState` but never reach a frame off-keystroke
    // — the "needs a keypress" bug. `publish_render_state` now returns
    // whether `paint_revision` moved so the actor's async arms can fire
    // `paint_request`; a no-op publish must return `false` (both to avoid
    // a spurious paint AND to keep the GPUI paint bridge's
    // run_tick_pending → re-publish from spinning).
    #[test]
    fn publish_render_state_paint_gate_tracks_non_cell_changes() {
        let mut editor = Editor::boot(lattice_core::Document::empty());
        // Baseline publish seeds `last_paint_revision`.
        let _ = editor.publish_render_state();
        // Nothing changed since: must NOT request a paint.
        assert!(
            !editor.publish_render_state(),
            "a no-op publish must not request a paint (loop-safety)"
        );
        // A minibuffer edit is a non-cell surface (RenderState.modeline —
        // here the search line), invisible to the cells MatrixVersion — it
        // MUST flip the gate.
        editor.open_search_line(lattice_grammar::SearchDirection::Forward);
        editor.set_search_line_text("x");
        assert!(
            editor.publish_render_state(),
            "a non-cell (minibuffer) change must request a paint"
        );
        // And settle back to a no-op once republished.
        assert!(
            !editor.publish_render_state(),
            "a settled publish must not request a paint"
        );
        // The cursor is an OVERLAY (deliberately absent from the cells
        // MatrixVersion — lattice-cells/src/version.rs), so a cursor-only
        // move is exactly the class that used to need a keypress.
        // Move the cursor to a position it's not already at (the search
        // line set above left it at (0, byte=1)).
        editor.cursor = lattice_protocol::Position::new(0, 2);
        assert!(
            editor.publish_render_state(),
            "a cursor-only move (overlay) must request a paint"
        );
        assert!(
            !editor.publish_render_state(),
            "a settled publish must not request a paint"
        );
    }

    /// NOTIF: a notification arriving with no keystroke in flight must
    /// flip the paint gate.
    ///
    /// The corner is fed by a store the actor does not own, so nothing
    /// else in `compute_paint_revision` moves when one is posted. That
    /// was the second half of the invisible-completion bug: even once
    /// the store learned to wake the editor, the wake reached a publish
    /// that reported "nothing moved", so `paint_request` never fired
    /// and a `magit push` completion still waited for a keypress.
    #[test]
    fn publish_render_state_paint_gate_tracks_notifications() {
        // `services` is an `Arc`, so the store goes in before the
        // Editor is built — same shape as
        // `editor_with_highlights_service`.
        let store: lattice_notify::NotificationStoreHandle =
            std::sync::Arc::new(lattice_notify::NotificationStore::new());
        let mut registry = lattice_mode::ServiceRegistry::new();
        registry.register(store.clone());
        let mut editor = Editor {
            services: std::sync::Arc::new(registry),
            ..Default::default()
        };

        let _ = editor.publish_render_state();
        assert!(
            !editor.publish_render_state(),
            "a no-op publish must not request a paint"
        );

        store.post(
            lattice_notify::NotificationLevel::Info,
            "push: everything up-to-date",
        );
        assert!(
            editor.publish_render_state(),
            "a posted notification must request a paint without a keystroke"
        );
        assert!(
            !editor.publish_render_state(),
            "a settled publish must not request a paint"
        );

        // Removal is the same surface in the other direction: an
        // expired notification has to stop being painted on its own.
        store.dismiss_all();
        assert!(
            editor.publish_render_state(),
            "a dismissed notification must request a paint without a keystroke"
        );
    }

    // §12 paint gate: a suppressed (batched) publish returns `false` —
    // the real publish at batch-unwind reports the net change, so the
    // off-keystroke arms paint exactly once for a batch.
    #[test]
    fn publish_render_state_suppressed_during_batch_returns_false() {
        let mut editor = Editor::default();
        let _ = editor.publish_render_state();
        editor
            .publish_cache
            .lock()
            .expect("publish_cache mutex poisoned")
            .publish_batch_depth = 1;
        editor.auto_submit_after_chord = true;
        assert!(
            !editor.publish_render_state(),
            "a publish suppressed inside a batch must return false even when state changed"
        );
    }

