    /// `do_diff_accept` against a two-pane session bound
    /// to a completion sender: fires `DiffOutcome::Accept`
    /// on the channel, then tears down. Verifies the
    /// programmatic-consumer flow (a magit plugin /
    /// openDiff caller binds a sender and awaits the
    /// signal).
    #[tokio::test]
    async fn do_diff_accept_fires_accept_signal_and_tears_down() {
        use tokio::sync::oneshot;
        let mut editor = Editor::default();
        let (_a, ab, _o, _ob) = vsplit_two_buffers(&mut editor);

        // Stage + complete a two-pane session via
        // :diffthis x2.
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        let primary = editor
            .diff_subsystem
            .lookup_session_for(ab)
            .expect("session exists after :diffthis")
            .buffer_id();

        // Bind a completion sender post-hoc.
        let (tx, rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor
            .diff_subsystem
            .lookup(primary)
            .expect("session present")
            .bind_completion(tx);

        // Now accept. Should fire Accept and drop the session.
        editor.do_diff_accept();
        assert!(
            editor.diff_subsystem.is_empty(),
            "session should be torn down after :diff-accept"
        );

        // Receiver gets Accept (sync — already sent before
        // teardown returned, so the recv is immediate).
        let outcome = rx.await.expect("sender fired before drop");
        assert_eq!(outcome, crate::diff::subsystem::DiffOutcome::Accept);
    }

    /// `do_diff_reject` mirrors `do_diff_accept` but fires
    /// `DiffOutcome::Reject`.
    #[tokio::test]
    async fn do_diff_reject_fires_reject_signal_and_tears_down() {
        use tokio::sync::oneshot;
        let mut editor = Editor::default();
        let (_a, ab, _o, _ob) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        let primary = editor
            .diff_subsystem
            .lookup_session_for(ab)
            .expect("session exists")
            .buffer_id();
        let (tx, rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor
            .diff_subsystem
            .lookup(primary)
            .expect("session present")
            .bind_completion(tx);

        editor.do_diff_reject();
        assert!(editor.diff_subsystem.is_empty());
        let outcome = rx.await.expect("sender fired before drop");
        assert_eq!(outcome, crate::diff::subsystem::DiffOutcome::Reject);
    }

    // ── I4 (Claude Code IDE peer, openDiff): programmatic diff ──

    /// `open_programmatic_diff` opens a two-pane side-by-side diff
    /// (original left / proposed right), binds the request's completion
    /// oneshot to the registered session, and records the Accept save
    /// target. `:diff-accept` fires `Accept` back to the awaiting
    /// producer — the openDiff blocking-await contract.
    #[tokio::test]
    async fn open_programmatic_diff_side_by_side_accept_fires_completion() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-i4-open-diff-accept.rs");
        std::fs::write(&path, "fn main() {}\n").expect("write baseline");

        let mut editor = Editor::default();
        // Register core options so `activate_buffer_state`'s option resolution
        // doesn't panic (production registers these at boot).
        editor.config.init_from_linkme();
        assert_eq!(editor.pane_tree.len(), 1, "starts single-pane");
        // D-fix.1: the starting pane stands in for the `:claude` terminal pane —
        // it must SURVIVE the diff (Option A: claude stays put).
        let origin_pane = editor.pane_tree.active().id;
        let origin_buf = editor.active_pane_buffer_id();

        let (tx, rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "fn main() { todo!() }\n".to_string(),
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });

        // D-fix.1 (Option A): the origin (claude) pane is preserved and the diff
        // opens in TWO fresh panes to its right → `origin | baseline | proposed`.
        assert_eq!(
            editor.pane_tree.len(),
            3,
            "openDiff keeps the claude pane and opens baseline + proposed beside it"
        );
        assert_eq!(
            editor.pane_tree.leaves()[0].id,
            origin_pane,
            "the origin (claude) pane survives at slot 0"
        );
        assert_eq!(
            editor.pane_tree.leaves()[0].buffer_id,
            origin_buf,
            "the origin pane still holds the claude buffer (not clobbered by baseline)"
        );
        let right_id = editor.active_pane_buffer_id();
        assert_eq!(
            editor.pane_tree.leaves()[2].buffer_id,
            right_id,
            "proposed buffer is the RIGHTmost pane and is active"
        );
        let baseline_id = editor.pane_tree.leaves()[1].buffer_id;
        assert_ne!(baseline_id, right_id, "the middle pane holds the baseline");
        assert_ne!(baseline_id, origin_buf, "baseline is distinct from claude");
        let session = editor
            .diff_subsystem
            .lookup_session_for(right_id)
            .expect("a diff session is registered for the proposed buffer");
        assert_eq!(
            session.buffer_id(),
            right_id,
            "primary = the proposed buffer"
        );
        assert_eq!(
            editor.programmatic_diff_accept_paths.get(&right_id),
            Some(&path),
            "the Accept save target is recorded against the proposed buffer"
        );

        // The producer is awaiting `rx`; :diff-accept fires Accept + tears down.
        editor.do_diff_accept();
        assert!(
            editor.diff_subsystem.is_empty(),
            "session torn down after accept"
        );
        let outcome = rx
            .await
            .expect("completion fired before the sender dropped");
        assert_eq!(outcome, crate::diff::subsystem::DiffOutcome::Accept);

        // D-fix.1: the diff closes on accept and focus returns to claude.
        assert_eq!(
            editor.pane_tree.len(),
            1,
            "both diff panes close on accept — only the claude pane remains"
        );
        assert_eq!(
            editor.active_pane_buffer_id(),
            origin_buf,
            "focus returns to the claude pane after accept"
        );
        assert!(
            editor.buffers.kind_of(baseline_id).is_none(),
            "the throwaway baseline buffer is removed from the registry"
        );
        assert!(
            editor.buffers.kind_of(right_id).is_none(),
            "the throwaway proposed buffer is removed from the registry"
        );
        assert!(
            editor.programmatic_diff_panes.is_empty(),
            "the pane-teardown record is cleaned on accept"
        );

        // FILE_SAVED contract: the accept wrote the proposed content to disk.
        assert_eq!(
            std::fs::read_to_string(&path).expect("baseline file readable"),
            "fn main() { todo!() }\n",
            "accept persists the proposed (right) side to old_file_path"
        );
        // The accept-path map entry was cleaned up on teardown.
        assert!(
            editor.programmatic_diff_accept_paths.is_empty(),
            "the accept save target is removed on teardown"
        );

        let _ = std::fs::remove_file(&path);
    }

    /// D-fix.2: BOTH diff panes (baseline + proposed) get a tree-sitter syntax
    /// handle for the file's language, so each highlights — not just the active
    /// one. Baseline highlights via its buffer-local (it's the inactive pane).
    #[tokio::test]
    async fn open_programmatic_diff_highlights_both_panes() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-i4-open-diff-syntax.rs");
        std::fs::write(&path, "fn main() {}\n").expect("write baseline");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        // The derived `Editor::default()` carries an empty `lang_registry`;
        // install the standard one (as boot does) so the Rust grammar resolves
        // for `.rs`. Without this, both handles would be None (plain-text).
        editor.lang_registry =
            lattice_syntax::LangRegistry::standard().expect("standard lang registry");

        let (tx, _rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "fn main() { todo!() }\n".to_string(),
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });

        let proposed_id = editor.active_pane_buffer_id();
        let baseline_id = editor.pane_tree.leaves()[1].buffer_id;
        assert!(
            editor.document_syntax_for(proposed_id).is_some(),
            "the active (proposed) pane has a syntax handle"
        );
        assert!(
            editor.document_syntax_for(baseline_id).is_some(),
            "the inactive (baseline) pane ALSO highlights (via its buffer-local)"
        );

        let _ = std::fs::remove_file(&path);
    }

    /// D-fix.5: openDiff auto-scrolls the proposed (active) pane to the
    /// first change. The synchronous `recompute_blocking` in
    /// `open_programmatic_diff` publishes the hunks, so
    /// `first_change_line` resolves immediately and the cursor lands on
    /// the changed line (vim positions at the first diff on open).
    #[tokio::test]
    async fn open_programmatic_diff_scrolls_to_first_change() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-dfix5-autoscroll.txt");
        // 30 identical lines; the proposed side changes line 15.
        let baseline: String = (0..30).map(|i| format!("line{i}\n")).collect();
        std::fs::write(&path, &baseline).expect("write baseline");
        let mut proposed_lines: Vec<String> = (0..30).map(|i| format!("line{i}")).collect();
        proposed_lines[15] = "CHANGED".to_string();
        let proposed: String = proposed_lines.iter().map(|l| format!("{l}\n")).collect();

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let (tx, _rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: proposed,
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });

        // The active pane is the proposed (right) side; its cursor sits
        // on the first (only) change at line 15.
        assert_eq!(
            editor.cursor.line, 15,
            "auto-scroll positions the proposed pane's cursor at the first change"
        );
        let _ = std::fs::remove_file(&path);
    }

    /// D-fix.5: `recompute_folds_for_buffer` computes + stashes folds for
    /// an INACTIVE buffer (the baseline pane of a side-by-side diff). This
    /// is the substrate gap both-sides folding needs — `recompute_folds`
    /// only ever folds the active buffer. Register an `UnchangedFoldSource`
    /// for the inactive baseline, then assert the recompute writes closed
    /// unchanged folds into its `DocumentFolds` buffer-local.
    #[tokio::test]
    async fn recompute_folds_for_inactive_baseline_stashes_unchanged_folds() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-dfix5-inactive-folds.txt");
        // 30 lines; proposed changes line 15 → a Change hunk both sides.
        let baseline: String = (0..30).map(|i| format!("line{i}\n")).collect();
        std::fs::write(&path, &baseline).expect("write baseline");
        let mut proposed_lines: Vec<String> = (0..30).map(|i| format!("line{i}")).collect();
        proposed_lines[15] = "CHANGED".to_string();
        let proposed: String = proposed_lines.iter().map(|l| format!("{l}\n")).collect();

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let (tx, _rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: proposed,
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });

        // Baseline (left) is the inactive pane; slot 0.
        let baseline_id = editor.pane_tree.leaves()[1].buffer_id;
        let session = editor
            .diff_subsystem
            .lookup_session_for(baseline_id)
            .expect("session for the baseline participant");
        // The synchronous open compute published hunks + per-slot line
        // counts; register the unchanged-fold source the mode would
        // (slot 0, defaults via None) directly through the fold service.
        let svc = crate::fold_provider::FoldOverlayServiceImpl::new(editor.fold_registry.clone());
        let source: std::sync::Arc<dyn lattice_core::FoldSource> = std::sync::Arc::new(
            lattice_diff::fold::UnchangedFoldSource::new(session, baseline_id, 0, None),
        );
        lattice_core::FoldOverlayService::add_source(&svc, source, baseline_id);

        // Recompute for the INACTIVE buffer → stashes DocumentFolds.
        editor.recompute_folds_for_buffer(baseline_id);

        let folds = editor
            .buffer_locals
            .get(&baseline_id)
            .and_then(|l| l.get::<crate::modes::DocumentFolds>())
            .map(|f| f.0.clone())
            .unwrap_or_default();
        assert!(
            !folds.is_empty(),
            "inactive baseline gets unchanged folds stashed"
        );
        assert!(
            folds.iter().all(|f| f.closed),
            "unchanged folds are closed by default"
        );
        // The change row (baseline line 15) is within the kept context
        // window, never inside a fold.
        assert!(
            !folds.iter().any(|f| f.start_line <= 15 && 15 <= f.end_line),
            "the change line stays visible (context kept)"
        );
        let _ = std::fs::remove_file(&path);
    }

    /// With MORE than one pending review, `:diff-accept` does NOT silently
    /// resolve one — it opens the diff-review picker so the user chooses which.
    /// The reviews stay pending (nothing fires) until a row is accepted.
    #[tokio::test]
    async fn multiple_pending_reviews_open_a_picker() {
        use tokio::sync::oneshot;
        let mut p1 = std::env::temp_dir();
        p1.push("lattice-diff-multi-1.rs");
        std::fs::write(&p1, "a\n").expect("write p1");
        let mut p2 = std::env::temp_dir();
        p2.push("lattice-diff-multi-2.rs");
        std::fs::write(&p2, "b\n").expect("write p2");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let (tx1, mut rx1) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: p1.clone(),
            new_file_path: p1.clone(),
            new_contents: "a2\n".to_string(),
            tab_name: "one".to_string(),
            origin_session: 1,
            response: tx1,
        });
        let (tx2, mut rx2) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: p2.clone(),
            new_file_path: p2.clone(),
            new_contents: "b2\n".to_string(),
            tab_name: "two".to_string(),
            origin_session: 1,
            response: tx2,
        });
        assert_eq!(
            editor.diff_subsystem.sessions_awaiting_outcome().len(),
            2,
            "two pending agent reviews"
        );

        // >1 pending → the verdict opens a picker rather than resolving one.
        editor.do_diff_accept();
        assert!(
            editor.picker.is_some(),
            ">1 reviews ⇒ diff-review picker opens"
        );
        assert_eq!(
            editor.diff_subsystem.sessions_awaiting_outcome().len(),
            2,
            "picker doesn't resolve anything; the user still chooses"
        );
        assert!(
            matches!(rx1.try_recv(), Err(oneshot::error::TryRecvError::Empty)),
            "review 1 still pending"
        );
        assert!(
            matches!(rx2.try_recv(), Err(oneshot::error::TryRecvError::Empty)),
            "review 2 still pending"
        );

        let _ = std::fs::remove_file(&p1);
        let _ = std::fs::remove_file(&p2);
    }

    /// `:diff-reject` on a programmatic diff fires `Reject` to the producer.
    #[tokio::test]
    async fn open_programmatic_diff_reject_fires_completion() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-i4-open-diff-reject.rs");
        std::fs::write(&path, "old\n").expect("write baseline");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let origin_buf = editor.active_pane_buffer_id();
        let (tx, rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "new\n".to_string(),
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });
        assert_eq!(
            editor.pane_tree.len(),
            3,
            "claude pane + baseline + proposed"
        );

        editor.do_diff_reject();
        let outcome = rx
            .await
            .expect("completion fired before the sender dropped");
        assert_eq!(outcome, crate::diff::subsystem::DiffOutcome::Reject);
        assert!(editor.diff_subsystem.is_empty());

        // D-fix.1: reject also closes the diff and returns focus to claude.
        assert_eq!(
            editor.pane_tree.len(),
            1,
            "both diff panes close on reject — only the claude pane remains"
        );
        assert_eq!(
            editor.active_pane_buffer_id(),
            origin_buf,
            "focus returns to the claude pane after reject"
        );
        assert!(editor.programmatic_diff_panes.is_empty());

        // Reject discards: the baseline file is untouched, the map is cleaned.
        assert_eq!(
            std::fs::read_to_string(&path).expect("baseline file readable"),
            "old\n",
            "reject leaves old_file_path unchanged"
        );
        assert!(editor.programmatic_diff_accept_paths.is_empty());

        let _ = std::fs::remove_file(&path);
    }

    /// Closing the proposed buffer mid-diff (the agent's `close_tab`, or `:bd`)
    /// cancels the openDiff: the session is torn down, the accept-path map is
    /// cleaned, and the bound completion sender drops WITHOUT a verdict — so the
    /// awaiting producer sees a recv error it maps to a reject (never a hang).
    #[tokio::test]
    async fn open_programmatic_diff_close_tab_cancels_with_reject() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-i4-open-diff-cancel.rs");
        std::fs::write(&path, "old\n").expect("write baseline");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let (tx, rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "new\n".to_string(),
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });
        let proposed = editor.active_pane_buffer_id();
        assert!(
            editor.diff_subsystem.lookup_session_for(proposed).is_some(),
            "session is live before the close"
        );

        // Close the proposed buffer mid-diff (force past the dirty guard).
        editor.do_buffer_delete(true);

        assert!(
            editor.diff_subsystem.is_empty(),
            "session torn down when its participant is closed"
        );
        assert!(
            editor.programmatic_diff_panes.is_empty(),
            "D-fix.1: the pane-teardown record is cleaned on cancel (no leak)"
        );
        assert!(
            editor.programmatic_diff_accept_paths.is_empty(),
            "accept save target cleaned on cancel"
        );
        assert!(
            rx.await.is_err(),
            "the bound sender dropped with no verdict → the producer rejects"
        );
        // Nothing was written: the baseline is unchanged.
        assert_eq!(
            std::fs::read_to_string(&path).expect("baseline file readable"),
            "old\n"
        );

        let _ = std::fs::remove_file(&path);
    }

    /// D-fix.6: a session-scoped close tears down ONLY the issuing
    /// connection's diffs, never another session's. This is the load-bearing
    /// isolation guarantee for concurrent agent sessions — connection 1's
    /// `close_tab` / `closeAllDiffTabs` must not touch connection 2's diff.
    #[tokio::test]
    async fn close_session_diffs_is_scoped_to_its_connection() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-dfix6-scope.rs");
        std::fs::write(&path, "base\n").expect("write baseline");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();

        // Connection 1 opens a diff.
        let (tx1, mut rx1) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "one\n".to_string(),
            tab_name: "conn1".to_string(),
            origin_session: 1,
            response: tx1,
        });
        let prop1 = editor.active_pane_buffer_id();

        // Connection 2 opens a SECOND diff.
        let (tx2, mut rx2) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "two\n".to_string(),
            tab_name: "conn2".to_string(),
            origin_session: 2,
            response: tx2,
        });
        let prop2 = editor.active_pane_buffer_id();
        assert_ne!(prop1, prop2);
        assert_eq!(
            editor.programmatic_diff_panes.len(),
            2,
            "both diffs registered"
        );

        // Close connection 1's diffs only.
        let closed = editor.do_close_session_diffs(1);
        assert_eq!(closed, 1, "exactly connection 1's one diff torn down");

        // Connection 1: rejected + cleaned.
        assert_eq!(
            rx1.try_recv(),
            Ok(crate::diff::subsystem::DiffOutcome::Reject),
            "connection 1's openDiff resolves Reject"
        );
        assert!(
            editor.diff_subsystem.lookup_session_for(prop1).is_none(),
            "conn1 session gone"
        );
        assert!(
            !editor.programmatic_diff_panes.contains_key(&prop1),
            "conn1 pane record removed"
        );

        // Connection 2: UNTOUCHED — still open, oneshot still pending.
        assert!(
            matches!(rx2.try_recv(), Err(oneshot::error::TryRecvError::Empty)),
            "conn2's openDiff is still pending (not rejected by conn1's close)"
        );
        assert!(
            editor.diff_subsystem.lookup_session_for(prop2).is_some(),
            "conn2 session alive"
        );
        assert!(
            editor.programmatic_diff_panes.contains_key(&prop2),
            "conn2 pane record intact"
        );

        let _ = std::fs::remove_file(&path);
    }

    /// D-fix.6: the `0` sentinel (a non-IDE producer's diff) and an unknown
    /// connection match nothing — a stray / mis-scoped close can never sweep
    /// every diff.
    #[tokio::test]
    async fn close_session_diffs_ignores_zero_and_unknown_sessions() {
        use tokio::sync::oneshot;
        let mut path = std::env::temp_dir();
        path.push("lattice-dfix6-zero.rs");
        std::fs::write(&path, "base\n").expect("write baseline");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let (tx, _rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            new_contents: "x\n".to_string(),
            tab_name: "no-session".to_string(),
            origin_session: 0, // a non-IDE producer
            response: tx,
        });
        assert_eq!(editor.programmatic_diff_panes.len(), 1);

        assert_eq!(
            editor.do_close_session_diffs(0),
            0,
            "the 0 sentinel matches nothing"
        );
        assert_eq!(
            editor.do_close_session_diffs(5),
            0,
            "an unknown connection matches nothing"
        );
        assert_eq!(
            editor.programmatic_diff_panes.len(),
            1,
            "the diff is untouched by a non-matching close"
        );

        let _ = std::fs::remove_file(&path);
    }

    /// User edits to the proposed (right) side during review ARE persisted on
    /// Accept: the accept hook writes the buffer's LIVE content (read via the
    /// registry handle, which shares the active document's backing actor), not
    /// the original `new_contents`. So a human can tweak the agent's proposal in
    /// the diff and have those tweaks land on disk.
    #[tokio::test]
    async fn open_programmatic_diff_persists_user_edits_to_the_proposed_side() {
        use lattice_protocol::edit::Edit;
        use lattice_protocol::position::Position;
        use tokio::sync::oneshot;

        let mut path = std::env::temp_dir();
        path.push("lattice-i4-open-diff-user-edit.rs");
        std::fs::write(&path, "fn main() {}\n").expect("write baseline");

        let mut editor = Editor::default();
        editor.config.init_from_linkme();
        let (tx, rx) = oneshot::channel::<crate::diff::subsystem::DiffOutcome>();
        editor.open_programmatic_diff(lattice_diff::ProgrammaticDiffRequest {
            old_file_path: path.clone(),
            new_file_path: path.clone(),
            // Proposed starts equal to the baseline; the *user* is the one who
            // changes it below.
            new_contents: "fn main() {}\n".to_string(),
            tab_name: "demo".to_string(),
            origin_session: 0,
            response: tx,
        });

        // The proposed (right) buffer is the active document after open. The
        // user edits it — insert a line at the top (the same path real
        // keystrokes take through `apply_edit_blocking`).
        let proposed = editor.active_pane_buffer_id();
        editor
            .apply_edit_blocking(Edit::insert(Position::ZERO, "// human tweak\n"))
            .expect("edit applies to the editable proposed buffer");

        // Accept writes the LIVE (edited) content, not the original proposal.
        editor.do_diff_accept();
        let outcome = rx.await.expect("completion fired");
        assert_eq!(outcome, crate::diff::subsystem::DiffOutcome::Accept);

        let saved = std::fs::read_to_string(&path).expect("baseline file readable");
        assert_eq!(
            saved, "// human tweak\nfn main() {}\n",
            "the user's edit to the proposed side is what gets saved (buffer {})",
            proposed.0
        );

        let _ = std::fs::remove_file(&path);
    }

    /// Sessions without a bound completion are still
    /// torn down cleanly by `do_diff_accept` —
    /// `take_completion()` returns None, the teardown
    /// proceeds without firing a signal.
    #[tokio::test]
    async fn do_diff_accept_without_bound_completion_still_tears_down() {
        let mut editor = Editor::default();
        let _ = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        assert!(
            !editor.diff_subsystem.is_empty(),
            "session exists after :diffthis x2"
        );
        editor.do_diff_accept();
        assert!(
            editor.diff_subsystem.is_empty(),
            "session torn down even without a bound completion"
        );
    }

    // ── D.6.g: :diffoff! cascade tear-down ─────────────────

    /// `:diffoff!` on a buffer with a single session is
    /// operationally identical to `:diffoff` (the
    /// regression guard for the bang's "subset of normal"
    /// semantics in the common case).
    #[tokio::test]
    async fn do_diff_off_bang_with_single_session_matches_unbang() {
        let mut editor = Editor::default();
        let _ = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        assert!(!editor.diff_subsystem.is_empty());
        // Force-bang on a single-session buffer.
        editor.do_diff_off(true);
        assert!(
            editor.diff_subsystem.is_empty(),
            "single-session :diffoff! tears down the session"
        );
        // Message: when force=true and count == 1, the
        // simple "Diff closed" form fires (no "(N sessions)"
        // suffix).
        let msg = editor.last_message.as_ref().expect("message set");
        assert_eq!(msg.text, "Diff closed");
    }

    /// **The key D.6.g case.** A shared buffer in two
    /// simultaneous sessions: plain `:diffoff` only closes
    /// one (the one secondary-index resolves to);
    /// `:diffoff!` cascades and closes both.
    #[tokio::test]
    async fn do_diff_off_bang_cascades_across_multiple_sessions() {
        use std::sync::Arc;
        let mut editor = Editor::default();

        // Set up three panes / three distinct buffer ids
        // so we can register two sessions that share a
        // common participant. Bypass the BufferRegistry
        // path — we directly invoke
        // `register_with_sources` because the test only
        // needs the subsystem-level wiring, not full UI
        // (pane groups / filler providers) lit up.
        use lattice_core::ui::pane::SplitOrientation;
        editor.pane_tree.split_active(SplitOrientation::Vertical);
        editor.pane_tree.split_active(SplitOrientation::Vertical);
        editor.pane_tree.leaves_mut()[1].buffer_id = lattice_core::BufferId(101);
        editor.pane_tree.leaves_mut()[2].buffer_id = lattice_core::BufferId(102);
        let shared = editor.pane_tree.leaves()[0].buffer_id;

        // Register two sessions through the shared buffer.
        let provider: Arc<dyn crate::diff::subsystem::BufferTextProvider> = Arc::new(
            crate::diff::subsystem::BufferRegistryTextProvider::new(editor.buffers.clone()),
        );
        let desc_a = crate::diff::subsystem::DiffDescriptor {
            sources: vec![
                Arc::new(crate::diff::subsystem::BufferSource::new(
                    Arc::clone(&provider),
                    shared,
                )),
                Arc::new(crate::diff::subsystem::BufferSource::new(
                    Arc::clone(&provider),
                    lattice_core::BufferId(101),
                )),
            ],
            watch: vec![shared, lattice_core::BufferId(101)],
            participants: vec![shared, lattice_core::BufferId(101)],
        };
        let desc_b = crate::diff::subsystem::DiffDescriptor {
            sources: vec![
                Arc::new(crate::diff::subsystem::BufferSource::new(
                    Arc::clone(&provider),
                    shared,
                )),
                Arc::new(crate::diff::subsystem::BufferSource::new(
                    Arc::clone(&provider),
                    lattice_core::BufferId(102),
                )),
            ],
            watch: vec![shared, lattice_core::BufferId(102)],
            participants: vec![shared, lattice_core::BufferId(102)],
        };
        editor.diff_subsystem.register_with_sources(
            lattice_core::BufferId(101),
            lattice_diff::DiffAlgorithm::Histogram,
            desc_a,
        );
        editor.diff_subsystem.register_with_sources(
            lattice_core::BufferId(102),
            lattice_diff::DiffAlgorithm::Histogram,
            desc_b,
        );
        assert_eq!(editor.diff_subsystem.len(), 2);

        // Cursor lives on the shared pane (pane 0). bang
        // cascades to both sessions.
        editor.pane_tree.set_active(0);
        editor.document_buffer_id = shared;
        editor.do_diff_off(true);

        assert!(
            editor.diff_subsystem.is_empty(),
            ":diffoff! must close every session the buffer participates in"
        );
        // Message names the count so the user knows the
        // bang actually did extra work.
        let msg = editor.last_message.as_ref().expect("message set");
        assert!(
            msg.text.contains("2 sessions"),
            "unexpected message: {}",
            msg.text
        );
    }

    /// Without the bang, only the secondary-index-resolved
    /// session is closed; the other survives.
    #[tokio::test]
    async fn do_diff_off_unbang_on_shared_buffer_closes_only_one_session() {
        use std::sync::Arc;
        let mut editor = Editor::default();
        use lattice_core::ui::pane::SplitOrientation;
        editor.pane_tree.split_active(SplitOrientation::Vertical);
        editor.pane_tree.split_active(SplitOrientation::Vertical);
        editor.pane_tree.leaves_mut()[1].buffer_id = lattice_core::BufferId(201);
        editor.pane_tree.leaves_mut()[2].buffer_id = lattice_core::BufferId(202);
        let shared = editor.pane_tree.leaves()[0].buffer_id;
        let provider: Arc<dyn crate::diff::subsystem::BufferTextProvider> = Arc::new(
            crate::diff::subsystem::BufferRegistryTextProvider::new(editor.buffers.clone()),
        );
        let mk = |peer: lattice_core::BufferId| crate::diff::subsystem::DiffDescriptor {
            sources: vec![
                Arc::new(crate::diff::subsystem::BufferSource::new(
                    Arc::clone(&provider),
                    shared,
                )),
                Arc::new(crate::diff::subsystem::BufferSource::new(
                    Arc::clone(&provider),
                    peer,
                )),
            ],
            watch: vec![shared, peer],
            participants: vec![shared, peer],
        };
        editor.diff_subsystem.register_with_sources(
            lattice_core::BufferId(201),
            lattice_diff::DiffAlgorithm::Histogram,
            mk(lattice_core::BufferId(201)),
        );
        editor.diff_subsystem.register_with_sources(
            lattice_core::BufferId(202),
            lattice_diff::DiffAlgorithm::Histogram,
            mk(lattice_core::BufferId(202)),
        );
        assert_eq!(editor.diff_subsystem.len(), 2);

        editor.pane_tree.set_active(0);
        editor.document_buffer_id = shared;
        editor.do_diff_off(false);
        // Exactly one session closed; the other survives.
        assert_eq!(
            editor.diff_subsystem.len(),
            1,
            ":diffoff (no bang) closes only the session secondary_index resolves to"
        );
    }

    // ── D.3.c: ]c / [c hunk navigation ─────────────────────

