    // ── D.5.b: do_diff_get end-to-end ──────────────────────

    /// Boot an editor (with a running document actor) over
    /// `current_text` and register a `StaticSource`-backed
    /// session over `baseline_text`. Cursor starts at (0, 0).
    fn boot_editor_with_diff_session(current_text: &str, baseline_text: &str) -> Editor {
        use crate::diff::subsystem::{
            BufferSource, BufferTextProvider, DiffDescriptor, StaticSource,
        };
        use lattice_diff::DiffAlgorithm;
        use ropey::Rope;
        use std::sync::Arc;

        // Sources-less BufferTextProvider stub for the
        // current side — compute_get_edit reads only the
        // baseline, so a None-returning provider suffices.
        #[derive(Debug)]
        struct NoneProvider;
        impl BufferTextProvider for NoneProvider {
            fn buffer_rope(&self, _: lattice_core::BufferId) -> Option<Rope> {
                None
            }
        }

        let document = lattice_core::Document::from_text(current_text);
        let editor = crate::editor::Editor::boot(document);
        let bid = editor.document_buffer_id;
        let provider: Arc<dyn BufferTextProvider> = Arc::new(NoneProvider);
        let desc = DiffDescriptor {
            sources: vec![
                Arc::new(StaticSource::new(Rope::from(baseline_text))),
                Arc::new(BufferSource::new(provider, bid)),
            ],
            watch: vec![bid],
            participants: vec![bid],
        };
        editor
            .diff_subsystem
            .register_with_sources(bid, DiffAlgorithm::Histogram, desc);
        editor
    }

    /// CR.1 test driver: the post-migration replacement for the deleted
    /// `editor.do_diff_get(target)`. Drives the SAME path the `do` chord
    /// now takes — `DiffSubsystem::diff_get_effect` (the resolver
    /// `DiffMode::action_handlers()` calls) → the host's
    /// `apply_diff_effect_inline` applier (`Effect::ApplyEdit` →
    /// `apply_targeted_edit`, or the error `Echo` → `set_message`).
    fn drive_diff_get(editor: &mut Editor, target: Option<lattice_core::BufferId>) {
        let eff = editor.diff_subsystem.diff_get_effect(
            editor.document_buffer_id,
            editor.cursor.line,
            target,
        );
        let mut out = DispatchOutcome::default();
        editor.apply_diff_effect_inline(eff, &mut out);
    }

    /// CR.1 test driver: the post-migration replacement for the deleted
    /// `editor.do_diff_put(target)`. Mirror of [`drive_diff_get`] for the
    /// put direction (`diff_put_effect`).
    fn drive_diff_put(editor: &mut Editor, target: Option<lattice_core::BufferId>) {
        let eff = editor.diff_subsystem.diff_put_effect(
            editor.document_buffer_id,
            editor.cursor.line,
            target,
        );
        let mut out = DispatchOutcome::default();
        editor.apply_diff_effect_inline(eff, &mut out);
    }

    /// CR.6 test drivers: the post-migration replacement for the deleted
    /// `editor.do_next_hunk()` / `do_prev_hunk()`. Drive the mode-owned
    /// `diff_next_hunk_effect` / `diff_prev_hunk_effect` resolver through
    /// the host applier (`Effect::SelectionChange` → cursor, or the
    /// no-session / no-hunks `Echo` → `set_message`).
    fn drive_next_hunk(editor: &mut Editor) {
        let eff = editor
            .diff_subsystem
            .diff_next_hunk_effect(editor.document_buffer_id, editor.cursor.line);
        let mut out = DispatchOutcome::default();
        editor.apply_diff_effect_inline(eff, &mut out);
    }

    fn drive_prev_hunk(editor: &mut Editor) {
        let eff = editor
            .diff_subsystem
            .diff_prev_hunk_effect(editor.document_buffer_id, editor.cursor.line);
        let mut out = DispatchOutcome::default();
        editor.apply_diff_effect_inline(eff, &mut out);
    }

    /// `do` on a Change hunk rewrites the current side's
    /// lines to match the baseline and parks the cursor at
    /// the hunk start. Verifies the full
    /// chord → Action → handler → apply_edit_blocking path.
    #[tokio::test]
    async fn do_diff_get_change_replaces_current_lines_with_baseline() {
        use lattice_diff::{Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        // Current: 3 lines; baseline: 3 lines; hunk
        // replaces current rows 0..3 with baseline rows 0..3.
        let mut editor = boot_editor_with_diff_session(
            "current-a\ncurrent-b\ncurrent-c\n",
            "baseline-a\nbaseline-b\nbaseline-c\n",
        );
        let bid = editor.document_buffer_id;
        let session = editor.diff_subsystem.lookup(bid).unwrap();
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Change,
                ranges: smallvec![LineRange::new(0, 3), LineRange::new(0, 3)],
                refine: Default::default(),
            }],
            algorithm: lattice_diff::DiffAlgorithm::Histogram,
            revision: rev,
        }));

        // Park cursor in the middle of the hunk.
        editor.cursor = lattice_protocol::position::Position::new(1, 0);
        drive_diff_get(&mut editor, None);

        // Buffer now matches the baseline.
        let snapshot = editor.document.snapshot();
        let text = snapshot.buffer.to_rope().to_string();
        assert_eq!(text, "baseline-a\nbaseline-b\nbaseline-c\n");
        // Cursor parks at the hunk start.
        assert_eq!(editor.cursor.line, 0);
        assert_eq!(editor.cursor.byte, 0);
    }

    /// CR.4 (2026-06-24): `]c` (next-hunk) lands on a `Conflict` hunk —
    /// conflicts ARE hunks, so the existing change-nav reaches them with
    /// no conflict-specific filter. This is the deliberate "confirmed,
    /// not filtered" choice: vim's `]c` = next change, and conflicts are
    /// among the changes (convention-first). Pins that `]c`/`[c` navigate
    /// to conflicts in a three-way session.
    #[tokio::test]
    async fn next_hunk_lands_on_conflict_hunk() {
        use lattice_diff::{Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        let mut editor = boot_editor_with_diff_session("a\nb\nc\nd\ne\n", "a\nb\nc\nd\ne\n");
        let bid = editor.document_buffer_id;
        let session = editor.diff_subsystem.lookup(bid).unwrap();
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Conflict,
                ranges: smallvec![LineRange::new(2, 3), LineRange::new(2, 3)],
                refine: Default::default(),
            }],
            algorithm: lattice_diff::DiffAlgorithm::Histogram,
            revision: rev,
        }));
        editor.cursor = lattice_protocol::position::Position::new(0, 0);
        // CR.6: drive the mode-owned resolver + the host applier (the
        // post-CR.6 replacement for the deleted `editor.do_next_hunk()`).
        let eff = editor
            .diff_subsystem
            .diff_next_hunk_effect(editor.document_buffer_id, editor.cursor.line);
        let mut out = DispatchOutcome::default();
        editor.apply_diff_effect_inline(eff, &mut out);
        assert_eq!(
            editor.cursor.line, 2,
            "]c should land on the conflict hunk start (conflicts are hunks)"
        );
    }

    /// No session → silent no-op; buffer + cursor unchanged.
    /// Per-buffer K.1.c filtering would normally suppress
    /// the chord, but the handler's own no-session guard
    /// keeps the action a no-op if anything ever invokes it
    /// directly.
    #[tokio::test]
    async fn do_diff_get_no_session_is_silent_noop() {
        let document = lattice_core::Document::from_text("unchanged\n");
        let mut editor = crate::editor::Editor::boot(document);
        let cursor_before = editor.cursor;
        let snapshot_before = editor.document.snapshot().buffer.to_rope().to_string();

        drive_diff_get(&mut editor, None);

        let snapshot_after = editor.document.snapshot().buffer.to_rope().to_string();
        assert_eq!(snapshot_before, snapshot_after);
        assert_eq!(editor.cursor, cursor_before);
    }

    /// CR.0: `Effect::ApplyEdit` against the active document edits the
    /// buffer + parks the cursor, end-to-end through the
    /// `handle_effect → Action::ApplyEdit → apply_targeted_edit`
    /// round-trip. `handle_effect` only TRANSLATES (defers the apply via
    /// `next_actions`); the edit lands when the action dispatches — proving
    /// the single-apply contract (risk #1). This is the generic primitive
    /// CR.1 migrates `do_diff_get`/`do_diff_put` onto.
    #[tokio::test]
    async fn apply_edit_effect_edits_active_buffer_and_parks_cursor() {
        let document = lattice_core::Document::from_text("alpha\nbeta\ngamma\n");
        let mut editor = crate::editor::Editor::boot(document);
        let target = editor.document_buffer_id;

        // Replace the whole second line ("beta") with "BETA".
        let edit = lattice_protocol::edit::Edit::replace(
            lattice_protocol::position::Range::new(
                lattice_protocol::position::Position::new(1, 0),
                lattice_protocol::position::Position::new(1, 4),
            ),
            "BETA",
        );

        // handle_effect translates ApplyEdit → Action::ApplyEdit on
        // next_actions; it does NOT apply the edit itself.
        let outcome = editor.handle_effect(lattice_grammar::Effect::ApplyEdit {
            target,
            edit,
            cursor: Some(lattice_protocol::position::Position::new(1, 0)),
        });
        assert!(
            matches!(outcome.next_actions.as_slice(), [Action::ApplyEdit { .. }]),
            "handle_effect should translate ApplyEdit into one \
             Action::ApplyEdit, got {:?}",
            outcome.next_actions
        );
        // Still unapplied — the action is pending.
        assert_eq!(
            editor.document.snapshot().buffer.to_rope().to_string(),
            "alpha\nbeta\ngamma\n"
        );

        // Drain the deferred action through the normal dispatch path.
        for action in outcome.next_actions {
            let _ = editor.dispatch(action);
        }

        assert_eq!(
            editor.document.snapshot().buffer.to_rope().to_string(),
            "alpha\nBETA\ngamma\n"
        );
        assert_eq!(editor.cursor.line, 1);
        assert_eq!(editor.cursor.byte, 0);
    }

    /// D.5.c: `dp` on a Change hunk pushes the current side's
    /// text into the peer buffer's range; the cursor parks
    /// at the hunk start on the current side (it didn't
    /// move, since the current side isn't mutated).
    ///
    /// Uses `do_diffsplit` to set up a real two-pane session
    /// with the registry populated for both sides. The
    /// manual `publish` overrides whatever the diffsplit
    /// auto-recompute produced (higher revision wins);
    /// `compute_put_plan` reads from the published hunks +
    /// the buffer-backed current source.
    #[tokio::test]
    async fn do_diff_put_change_pushes_current_into_peer_buffer() {
        use lattice_diff::{Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        // File becomes the current side after diffsplit;
        // baseline = the original empty document.
        let file = write_temp("current-a\ncurrent-b\n", "dp-change");
        let document = lattice_core::Document::empty();
        let mut editor = crate::editor::Editor::boot(document);
        let baseline_buffer = editor.document_buffer_id;
        editor.do_diffsplit(file.0.clone(), None);
        let current_buffer = editor.pane_tree.active().buffer_id;
        assert_ne!(current_buffer, baseline_buffer);

        // Drain the diffsplit's auto-recompute so our
        // manual publish is the final word before do_diff_put.
        tokio::task::yield_now().await;
        tokio::time::sleep(std::time::Duration::from_millis(60)).await;

        let session = editor
            .diff_subsystem
            .lookup(current_buffer)
            .expect("session keyed under current buffer");
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Add,
                // Baseline is empty (original Document::empty);
                // current has 2 lines from the file. Add hunk:
                // baseline empty range at row 0, current rows
                // 0..2.
                ranges: smallvec![LineRange::new(0, 0), LineRange::new(0, 2)],
                refine: Default::default(),
            }],
            algorithm: lattice_diff::DiffAlgorithm::Histogram,
            revision: rev,
        }));

        editor.cursor = lattice_protocol::position::Position::new(0, 0);
        drive_diff_put(&mut editor, None);

        // Peer (baseline) buffer now holds the current
        // side's content.
        let peer_handle = editor
            .buffers
            .document_handle(baseline_buffer)
            .expect("peer handle present");
        let peer_text = peer_handle.snapshot().buffer.to_rope().to_string();
        assert_eq!(peer_text, "current-a\ncurrent-b\n");
        // Cursor stays at the hunk start on the current side.
        assert_eq!(editor.cursor.line, 0);
        assert_eq!(editor.cursor.byte, 0);
    }

    /// D-fix.5 regression: BOTH sides of a side-by-side diff fold their
    /// unchanged regions — including the INACTIVE pane. The bug Dhruva hit:
    /// only the active buffer folded; the inactive baseline stayed expanded,
    /// desyncing the side-by-side view. Root cause: the inactive participant
    /// only ever folds via the activation-triggered recompute in
    /// `apply_pending_diff_mode_changes` (the active pane recovers via other
    /// `recompute_folds` triggers), and that recompute was missing — the
    /// per-tick `refresh_diff_folds` runs *before* the fold sources register
    /// and stamps the revision seen, blocking a later re-fold. The fix
    /// recomputes folds for each diff-mode-toggled buffer right after the
    /// source registers.
    #[tokio::test]
    async fn both_diff_panes_fold_unchanged_after_activation() {
        use lattice_diff::{Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        // 30-line baseline; the current side changes line 15. Plenty of
        // unchanged context above/below → unchanged folds on BOTH sides.
        let baseline: String = (0..30).map(|i| format!("line{i}\n")).collect();
        let mut cur_lines: Vec<String> = (0..30).map(|i| format!("line{i}")).collect();
        cur_lines[15] = "CHANGED".to_string();
        let current: String = cur_lines.iter().map(|l| format!("{l}\n")).collect();

        let file = write_temp(&current, "dfix5-bothfold");
        let document = lattice_core::Document::from_text(&baseline);
        let mut editor = crate::editor::Editor::boot(document);
        let baseline_buffer = editor.document_buffer_id;
        editor.do_diffsplit(file.0.clone(), None);
        let current_buffer = editor.pane_tree.active().buffer_id;
        assert_ne!(current_buffer, baseline_buffer);

        // Let the diffsplit's async recompute settle, then publish the final
        // hunks + per-slot line counts (slot 0 = baseline, slot 1 = current).
        tokio::task::yield_now().await;
        tokio::time::sleep(std::time::Duration::from_millis(60)).await;
        let session = editor
            .diff_subsystem
            .lookup(current_buffer)
            .expect("session keyed under current buffer");
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Change,
                ranges: smallvec![LineRange::new(15, 16), LineRange::new(15, 16)],
                refine: Default::default(),
            }],
            algorithm: lattice_diff::DiffAlgorithm::Histogram,
            revision: rev,
        }));
        session.publish_slot_line_counts(vec![31, 31]);

        // Activate diff-mode on both participants (the dispatch-tail drain).
        // The fix recomputes folds here, right after the sources register.
        editor.apply_pending_diff_mode_changes();

        // Active (current) side: folds live in `self.folds`.
        assert!(
            editor.folds.iter().any(|f| f.closed && f.end_line < 15),
            "active pane has a closed unchanged fold above the change, got {:?}",
            editor.folds
        );
        // INACTIVE (baseline) side: folds live in its `DocumentFolds`. This is
        // the regression — before the fix it was empty.
        let baseline_folds = editor
            .buffer_locals
            .get(&baseline_buffer)
            .and_then(|l| l.get::<crate::modes::DocumentFolds>())
            .map(|f| f.0.clone())
            .unwrap_or_default();
        assert!(
            baseline_folds.iter().any(|f| f.closed && f.end_line < 15),
            "INACTIVE baseline pane folds its unchanged regions too, got {:?}",
            baseline_folds
        );
    }

    /// D.5.c: `dp` against an inline (file-on-disk) baseline
    /// emits a clear error message instead of silently
    /// no-op'ing — vim parity for `:diff <file>` where the
    /// baseline isn't a live buffer.
    #[tokio::test]
    async fn do_diff_put_inline_baseline_emits_error_message() {
        use crate::diff::subsystem::{
            BufferSource, BufferTextProvider, DiffDescriptor, StaticSource,
        };
        use lattice_diff::{DiffAlgorithm, Hunk, HunkIndex, HunkKind, LineRange};
        use ropey::Rope;
        use smallvec::smallvec;

        #[derive(Debug)]
        struct NoneProvider;
        impl BufferTextProvider for NoneProvider {
            fn buffer_rope(&self, _: lattice_core::BufferId) -> Option<Rope> {
                None
            }
        }

        let document = lattice_core::Document::from_text("live-a\n");
        let mut editor = crate::editor::Editor::boot(document);
        let bid = editor.document_buffer_id;
        // Single-participant descriptor mirrors the
        // `:diff <file>` shape: file-on-disk baseline, no
        // peer buffer.
        let provider: std::sync::Arc<dyn BufferTextProvider> = std::sync::Arc::new(NoneProvider);
        let desc = DiffDescriptor {
            sources: vec![
                std::sync::Arc::new(StaticSource::new(Rope::from("base-a\n"))),
                std::sync::Arc::new(BufferSource::new(provider, bid)),
            ],
            watch: vec![bid],
            participants: vec![bid],
        };
        let session =
            editor
                .diff_subsystem
                .register_with_sources(bid, DiffAlgorithm::Histogram, desc);
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Change,
                ranges: smallvec![LineRange::new(0, 1), LineRange::new(0, 1)],
                refine: Default::default(),
            }],
            algorithm: DiffAlgorithm::Histogram,
            revision: rev,
        }));

        editor.cursor = lattice_protocol::position::Position::new(0, 0);
        let text_before = editor.document.snapshot().buffer.to_rope().to_string();
        drive_diff_put(&mut editor, None);

        // Error message surfaced, no document mutation.
        let msg = editor.last_message.as_ref().expect("error message set");
        assert!(
            msg.text.contains("baseline is not a buffer"),
            "expected NoPeerBuffer message, got: {}",
            msg.text
        );
        assert_eq!(msg.level, EchoLevel::Error);
        let text_after = editor.document.snapshot().buffer.to_rope().to_string();
        assert_eq!(
            text_before, text_after,
            "current buffer must not be mutated by inline `dp`"
        );
    }

    /// Cursor sitting outside every hunk → silent no-op.
    /// Matches the pure `compute_get_edit_cursor_outside_hunks`
    /// test but exercises the handler.
    #[tokio::test]
    async fn do_diff_get_cursor_outside_hunks_is_silent_noop() {
        use lattice_diff::{Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        let mut editor = boot_editor_with_diff_session("line-0\nline-1\nline-2\n", "alt\n");
        let bid = editor.document_buffer_id;
        let session = editor.diff_subsystem.lookup(bid).unwrap();
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Change,
                ranges: smallvec![LineRange::new(0, 1), LineRange::new(10, 11)],
                refine: Default::default(),
            }],
            algorithm: lattice_diff::DiffAlgorithm::Histogram,
            revision: rev,
        }));

        editor.cursor = lattice_protocol::position::Position::new(2, 0);
        let snapshot_before = editor.document.snapshot().buffer.to_rope().to_string();
        drive_diff_get(&mut editor, None);
        let snapshot_after = editor.document.snapshot().buffer.to_rope().to_string();
        assert_eq!(snapshot_before, snapshot_after);
        assert_eq!(editor.cursor.line, 2);
    }

    #[test]
    fn do_next_hunk_with_empty_hunkindex_messages_no_hunks() {
        let mut editor = Editor::default();
        let bid = editor.document_buffer_id;
        let _ = editor
            .diff_subsystem
            .register(bid, lattice_diff::DiffAlgorithm::Histogram);
        let before = editor.cursor;
        drive_next_hunk(&mut editor);
        let msg = editor.last_message.as_ref().expect("message set");
        assert!(msg.text.contains("no hunks"), "{}", msg.text);
        assert_eq!(editor.cursor, before);
    }

    // ── D.3.f.1 / DX.3-C7: mode-owned hunk folds through recompute_folds ─

    /// End-to-end: a diff session on the active buffer + diff-mode active
    /// produces a hunk fold in `editor.folds` after `recompute_folds()`.
    /// DX.3-C7: the `HunkFoldSource` is registered by
    /// `diff-mode::on_activate` (not a pre-seeded provider), so this
    /// exercises the full service-lookup → `FoldOverlayService::add_source`
    /// path. Boots a real editor so the fold + diff services are wired.
    #[tokio::test]
    async fn recompute_folds_adds_hunk_fold_when_diff_mode_active() {
        use lattice_diff::{DiffAlgorithm, Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        let mut editor =
            crate::editor::Editor::boot(lattice_core::Document::from_text("x\n".repeat(12)));
        let bid = editor.document_buffer_id;
        let session = editor
            .diff_subsystem
            .register(bid, DiffAlgorithm::Histogram);
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Add,
                ranges: smallvec![LineRange::new(3, 3), LineRange::new(3, 7)],
                refine: Default::default(),
            }],
            algorithm: DiffAlgorithm::Histogram,
            revision: 1,
        }));
        // Activate diff-mode on the buffer (the bridge change the dispatch
        // tail drains). `on_activate` registers the HunkFoldSource.
        editor
            .diff_subsystem
            .mode_bridge()
            .note_session_opened(bid, &[bid]);
        editor.apply_pending_diff_mode_changes();

        editor.recompute_folds();

        let hunk_fold = editor
            .folds
            .iter()
            .find(|f| f.start_line == 3 && f.end_line == 6);
        assert!(
            hunk_fold.is_some(),
            "expected one hunk fold at lines 3..=6 after diff-mode activation + \
             recompute, got {:?}",
            editor.folds
        );
        assert_eq!(
            hunk_fold.unwrap().identity,
            Some(crate::diff::fold::hunk_fold_identity(3, 6)),
            "hunk fold identity must namespace via diff:hunk hash"
        );
    }

    /// Closing the diff session deactivates diff-mode, whose `DiffModeGuard`
    /// Drop removes the `HunkFoldSource`; the next `recompute_folds()` drops
    /// the hunk fold (the Manual-foldmethod early-return clears stale
    /// overlay-sourced folds — DX.3-C7).
    #[tokio::test]
    async fn recompute_folds_drops_hunk_fold_when_session_closes() {
        use lattice_diff::{DiffAlgorithm, Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        let mut editor =
            crate::editor::Editor::boot(lattice_core::Document::from_text("x\n".repeat(12)));
        let bid = editor.document_buffer_id;
        let session = editor
            .diff_subsystem
            .register(bid, DiffAlgorithm::Histogram);
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Add,
                ranges: smallvec![LineRange::new(0, 0), LineRange::new(0, 4)],
                refine: Default::default(),
            }],
            algorithm: DiffAlgorithm::Histogram,
            revision: 1,
        }));
        editor
            .diff_subsystem
            .mode_bridge()
            .note_session_opened(bid, &[bid]);
        editor.apply_pending_diff_mode_changes();
        editor.recompute_folds();
        assert!(
            editor.folds.iter().any(|f| f.identity.is_some()),
            "sanity: diff-mode active → hunk fold present"
        );

        // `:diffoff` path — `drop_session` notifies the bridge to deactivate
        // diff-mode; the guard's Drop removes the fold source.
        editor.diff_subsystem.drop_session(bid);
        editor.apply_pending_diff_mode_changes();
        editor.recompute_folds();

        assert!(
            editor
                .folds
                .iter()
                .all(|f| f.identity != Some(crate::diff::fold::hunk_fold_identity(0, 3))),
            "after :diffoff (diff-mode off → source removed), the hunk fold must be gone"
        );
    }

    // ── D.4.a: PaneGroup registry + propagation ────────────

    /// Add → drop round-trip. The id returned by
    /// `add_pane_group` is the same one `drop_pane_group`
    /// accepts; the second drop is a no-op.
    #[test]
    fn pane_group_add_and_drop_round_trip() {
        use crate::pane_group::{IdentityRowMapper, PaneGroupMember};
        let mut editor = Editor::default();
        let active = editor
            .pane_tree
            .leaves()
            .first()
            .copied()
            .expect("at least one pane");
        let id = editor
            .add_pane_group(
                vec![PaneGroupMember {
                    pane: active.id,
                    buffer: active.buffer_id,
                }],
                std::sync::Arc::new(IdentityRowMapper),
            )
            .expect("registration ok");
        assert_eq!(editor.pane_groups.len(), 1);
        assert!(editor.drop_pane_group(id));
        assert_eq!(editor.pane_groups.len(), 0);
        assert!(
            !editor.drop_pane_group(id),
            "second drop is a no-op (returns false)"
        );
    }

    /// Two groups can't both claim the same active
    /// `(pane, buffer)` pair. The second registration errs.
    #[test]
    fn pane_group_rejects_duplicate_active_member() {
        use crate::pane_group::{IdentityRowMapper, PaneGroupMember};
        let mut editor = Editor::default();
        let active = editor.pane_tree.leaves()[0];
        let member = PaneGroupMember {
            pane: active.id,
            buffer: active.buffer_id,
        };
        editor
            .add_pane_group(vec![member], std::sync::Arc::new(IdentityRowMapper))
            .expect("first registration");
        let err = editor
            .add_pane_group(vec![member], std::sync::Arc::new(IdentityRowMapper))
            .expect_err("second registration with same pair must fail");
        assert!(err.contains("already in group"), "{err}");
    }

    /// Propagation: a 2-pane identity-mapper group, scroll
    /// on the active pane writes the *same* scroll into the
    /// other pane's stashed `PaneState.scroll`.
    #[test]
    fn pane_group_identity_propagation_2_pane() {
        use crate::pane_group::{IdentityRowMapper, PaneGroupMember};
        let mut editor = Editor::default();
        // Split to get a second pane.
        editor
            .pane_tree
            .split_active(lattice_core::ui::pane::SplitOrientation::Horizontal);
        // After split, leaves()[0] is the original (still
        // active by convention); leaves()[1] is the new one.
        let active = editor.pane_tree.leaves()[0];
        let other = editor.pane_tree.leaves()[1];
        editor
            .add_pane_group(
                vec![
                    PaneGroupMember {
                        pane: active.id,
                        buffer: active.buffer_id,
                    },
                    PaneGroupMember {
                        pane: other.id,
                        buffer: other.buffer_id,
                    },
                ],
                std::sync::Arc::new(IdentityRowMapper),
            )
            .expect("registration");
        // Set active pane's scroll and propagate.
        editor.scroll = 42;
        editor.propagate_pane_group_scroll();
        let other_after = editor
            .pane_tree
            .leaves()
            .iter()
            .find(|p| p.id == other.id)
            .expect("other pane present");
        assert_eq!(other_after.scroll, 42, "identity mapper copies row");
    }

    /// Buffer-mismatch suspends propagation: register a
    /// member, then switch the target pane's buffer to a
    /// different one; propagation must skip that pane.
    #[test]
    fn pane_group_propagation_suspended_on_buffer_mismatch() {
        use crate::pane_group::{IdentityRowMapper, PaneGroupMember};
        let mut editor = Editor::default();
        editor
            .pane_tree
            .split_active(lattice_core::ui::pane::SplitOrientation::Horizontal);
        let active = editor.pane_tree.leaves()[0];
        let other = editor.pane_tree.leaves()[1];
        editor
            .add_pane_group(
                vec![
                    PaneGroupMember {
                        pane: active.id,
                        buffer: active.buffer_id,
                    },
                    PaneGroupMember {
                        pane: other.id,
                        buffer: other.buffer_id,
                    },
                ],
                std::sync::Arc::new(IdentityRowMapper),
            )
            .expect("registration");
        // Mutate the other pane's buffer to a different one,
        // mimicking `:bn`. Stash a known scroll first so we
        // can prove it didn't change.
        let stash_marker = 1_234u32;
        editor
            .pane_tree
            .leaves_mut()
            .iter_mut()
            .find(|p| p.id == other.id)
            .expect("other pane")
            .scroll = stash_marker;
        editor
            .pane_tree
            .leaves_mut()
            .iter_mut()
            .find(|p| p.id == other.id)
            .expect("other pane")
            .buffer_id = lattice_core::BufferId(99_999);

        editor.scroll = 77;
        editor.propagate_pane_group_scroll();

        let other_after = editor
            .pane_tree
            .leaves()
            .iter()
            .find(|p| p.id == other.id)
            .expect("other pane present");
        assert_eq!(
            other_after.scroll, stash_marker,
            "buffer mismatch must suspend propagation — stashed scroll untouched"
        );
    }

    /// `remove_pane_group_member` drops the empty group
    /// once the last member is gone, so propagation isn't
    /// walking a zombie entry forever.
    #[test]
    fn remove_pane_group_member_prunes_empty_group() {
        use crate::pane_group::{IdentityRowMapper, PaneGroupMember};
        let mut editor = Editor::default();
        let active = editor.pane_tree.leaves()[0];
        let m = PaneGroupMember {
            pane: active.id,
            buffer: active.buffer_id,
        };
        let id = editor
            .add_pane_group(vec![m], std::sync::Arc::new(IdentityRowMapper))
            .expect("registration");
        assert!(editor.remove_pane_group_member(id, m));
        assert_eq!(
            editor.pane_groups.len(),
            0,
            "empty group must be pruned automatically"
        );
    }

    // ── D.0b: rebuild_scrollbind_group ──────────────────────────

    /// Helper: mark `buffer_id` as having scrollbind=`val` in
    /// `editor.resolved_options`. Bypasses `init_from_linkme`
    /// so the test can drive the option without a full boot.
    fn set_resolved_scrollbind(editor: &mut Editor, buffer_id: BufferId, val: bool) {
        editor
            .resolved_options
            .entry(buffer_id)
            .or_default()
            .insert::<lattice_config::Scrollbind>(val);
    }

    /// Single pane with scrollbind=true → no group created
    /// (need ≥ 2 panes for binding to be meaningful).
    #[test]
    fn scrollbind_single_pane_no_group() {
        let mut editor = Editor::default();
        let leaf = editor.pane_tree.leaves()[0];
        set_resolved_scrollbind(&mut editor, leaf.buffer_id, true);
        editor.rebuild_scrollbind_group();
        assert!(
            editor.scrollbind_group_id.is_none(),
            "single scrollbound pane must not create a group"
        );
        assert!(editor.pane_groups.is_empty());
    }

    /// Two panes both with scrollbind=true → group created and id
    /// stored; propagation follows identity mapper.
    #[test]
    fn scrollbind_two_panes_creates_group() {
        let mut editor = Editor::default();
        editor
            .pane_tree
            .split_active(lattice_core::ui::pane::SplitOrientation::Horizontal);
        let l0 = editor.pane_tree.leaves()[0];
        let l1 = editor.pane_tree.leaves()[1];
        set_resolved_scrollbind(&mut editor, l0.buffer_id, true);
        set_resolved_scrollbind(&mut editor, l1.buffer_id, true);

        editor.rebuild_scrollbind_group();

        assert!(
            editor.scrollbind_group_id.is_some(),
            "two scrollbound panes must create a group"
        );
        assert_eq!(editor.pane_groups.len(), 1);

        // Scroll propagation follows identity mapper.
        editor.scroll = 77;
        editor.propagate_pane_group_scroll();
        let l1_after = editor
            .pane_tree
            .leaves()
            .iter()
            .find(|p| p.id == l1.id)
            .expect("second leaf present");
        assert_eq!(l1_after.scroll, 77, "identity mapper propagates scroll");
    }

    /// Calling rebuild a second time with one pane now set to
    /// scrollbind=false drops the group and clears the id.
    #[test]
    fn scrollbind_toggle_off_drops_group() {
        let mut editor = Editor::default();
        editor
            .pane_tree
            .split_active(lattice_core::ui::pane::SplitOrientation::Horizontal);
        let l0 = editor.pane_tree.leaves()[0];
        let l1 = editor.pane_tree.leaves()[1];
        set_resolved_scrollbind(&mut editor, l0.buffer_id, true);
        set_resolved_scrollbind(&mut editor, l1.buffer_id, true);
        editor.rebuild_scrollbind_group();
        assert!(editor.scrollbind_group_id.is_some());

        // Turn off scrollbind on the second pane then rebuild.
        set_resolved_scrollbind(&mut editor, l1.buffer_id, false);
        editor.rebuild_scrollbind_group();

        assert!(
            editor.scrollbind_group_id.is_none(),
            "only one pane left with scrollbind=true; group must drop"
        );
        assert!(editor.pane_groups.is_empty());
    }

    /// Rebuilding twice when both panes remain bound must not
    /// accumulate extra groups — old group is replaced atomically.
    #[test]
    fn scrollbind_rebuild_is_idempotent() {
        let mut editor = Editor::default();
        editor
            .pane_tree
            .split_active(lattice_core::ui::pane::SplitOrientation::Horizontal);
        let l0 = editor.pane_tree.leaves()[0];
        let l1 = editor.pane_tree.leaves()[1];
        set_resolved_scrollbind(&mut editor, l0.buffer_id, true);
        set_resolved_scrollbind(&mut editor, l1.buffer_id, true);

        editor.rebuild_scrollbind_group();
        let id_first = editor.scrollbind_group_id.unwrap();
        editor.rebuild_scrollbind_group();
        let id_second = editor.scrollbind_group_id.unwrap();

        assert_ne!(id_first, id_second, "second rebuild mints a fresh group id");
        assert_eq!(
            editor.pane_groups.len(),
            1,
            "only one group must exist after double rebuild"
        );
    }

    // ── BL.1: do_set_local ──────────────────────────────────────

    /// Helper: boot the registry on an Editor so `parse_for_buffer_local`
    /// can look up option TypeIds.
    fn boot_config(editor: &mut Editor) {
        editor.config.init_from_linkme();
    }

    /// `:setlocal number=false` writes to buffer_local_overrides for the
    /// active buffer and does not touch the global registry value.
    #[test]
    fn set_local_writes_override_for_active_buffer() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf = editor.document_buffer_id;
        // Global value before: number=true (registered default).
        let global_before = *editor.config.get_typed::<lattice_config::Number>().unwrap();
        assert!(global_before, "global number must start true");
        editor.do_set_local("number=false");
        // Buffer-local override must be present.
        assert!(
            editor.buffer_local_overrides.contains_key(&buf),
            "buffer_local_overrides must have an entry for the active buffer"
        );
        assert_eq!(
            editor.buffer_local_overrides[&buf].len(),
            1,
            "exactly one override pushed"
        );
        // Global value must be unchanged.
        let global_after = *editor.config.get_typed::<lattice_config::Number>().unwrap();
        assert!(
            global_after,
            "global number must remain true after :setlocal"
        );
    }

    /// Two buffers get independent local overrides.
    #[test]
    fn set_local_overrides_are_per_buffer() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf_a = editor.document_buffer_id;
        editor.do_set_local("number=false");
        // Synthesize a second buffer id and point the active buffer at it.
        let buf_b = crate::buffers::BufferId(buf_a.0 + 1);
        editor.document_buffer_id = buf_b;
        editor.do_set_local("number=true");
        // buf_a retains its own override.
        assert!(editor.buffer_local_overrides.contains_key(&buf_a));
        // buf_b has its own independent override.
        assert!(editor.buffer_local_overrides.contains_key(&buf_b));
        assert_ne!(buf_a, buf_b);
    }

    /// `:setlocal number&` clears the override, reverting to global.
    #[test]
    fn set_local_name_ampersand_clears_override() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf = editor.document_buffer_id;
        editor.do_set_local("number=false");
        assert!(editor.buffer_local_overrides.contains_key(&buf));
        editor.do_set_local("number&");
        let set = editor.buffer_local_overrides.get(&buf);
        assert!(
            set.map(|s| s.is_empty()).unwrap_or(true),
            "override for `number` must be removed after `number&`"
        );
    }

    /// `:setlocal &` clears ALL overrides for the active buffer.
    #[test]
    fn set_local_bare_ampersand_clears_all_overrides() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf = editor.document_buffer_id;
        editor.do_set_local("number=false");
        editor.do_set_local("wrap=true");
        // Both overrides present.
        assert_eq!(
            editor.buffer_local_overrides.get(&buf).map(|s| s.len()),
            Some(2)
        );
        editor.do_set_local("&");
        assert!(
            !editor.buffer_local_overrides.contains_key(&buf),
            "`:setlocal &` must clear all buffer-local overrides"
        );
    }

    // ── BL.2: origin tracking + do_set_global ───────────────────

    /// `:setglobal number=false` writes the global registry only;
    /// buffer-local overrides are untouched.
    #[test]
    fn set_global_writes_registry_not_local_overrides() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf = editor.document_buffer_id;
        // Confirm global starts at its registered default.
        let before = *editor.config.get_typed::<lattice_config::Number>().unwrap();
        assert!(before, "number must start true");
        editor.do_set_global("number=false");
        // Global registry must reflect the new value.
        let after = *editor.config.get_typed::<lattice_config::Number>().unwrap();
        assert!(!after, "global number must be false after :setglobal");
        // Buffer-local overrides must be untouched.
        assert!(
            !editor.buffer_local_overrides.contains_key(&buf),
            ":setglobal must not create buffer-local overrides"
        );
    }

    /// After `:setlocal number=false`, the resolved options for the
    /// active buffer carry `OptionOrigin::BufferLocal` for `number`.
    #[test]
    fn resolved_origin_is_buffer_local_after_set_local() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf = editor.document_buffer_id;
        editor.do_set_local("number=false");
        let resolved = editor
            .resolved_options
            .get(&buf)
            .expect("must have resolved");
        let origin = resolved.get_origin::<lattice_config::Number>();
        assert_eq!(
            origin,
            lattice_config::OptionOrigin::BufferLocal,
            "after :setlocal the origin must be BufferLocal"
        );
    }

    /// Without any local override, the resolved origin is GlobalConfig.
    #[test]
    fn resolved_origin_is_global_config_without_local_override() {
        let mut editor = Editor::default();
        boot_config(&mut editor);
        let buf = editor.document_buffer_id;
        // Force a recompute with no local overrides.
        editor.recompute_options_for_buffer(buf);
        let resolved = editor
            .resolved_options
            .get(&buf)
            .expect("must have resolved");
        let origin = resolved.get_origin::<lattice_config::Number>();
        assert_eq!(
            origin,
            lattice_config::OptionOrigin::GlobalConfig,
            "without a local override the origin must be GlobalConfig"
        );
    }

