    /// PU-B.1/2b: `Effect::OpenPopup` has no host apply arm — it is
    /// renderer-coupled, so `apply_effect_host` must push it onto
    /// `out.effects` (the tail the TUI / GPUI peers drain to call
    /// `open_popup_named`) rather than swallow it. This pins the routing
    /// decision independent of any `lattice-ai` consumer.
    #[test]
    fn open_popup_effect_routes_to_renderer_tail() {
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::empty());
        let mut out = DispatchOutcome::default();

        apply_effect_host(
            &mut editor,
            lattice_grammar::Effect::OpenPopup {
                name: "*ai-permission*".to_string(),
                mode_id: "ai-permission-mode".to_string(),
                placement: crate::popup::PopupPlacement::Centered,
                focus: crate::popup::PopupFocus::Steal,
            },
            &mut out,
        );

        assert!(
            out.effects.iter().any(|e| matches!(
                e,
                lattice_grammar::Effect::OpenPopup { name, .. } if name == "*ai-permission*"
            )),
            "OpenPopup reaches the renderer-coupled tail, not the host catch-all"
        );
    }

    /// PU-B.2b: `open_popup_named` ensures a `BufferData::Help` popup buffer
    /// under the given major mode (so the popup renderer draws it) and shows it
    /// Steal-focused — the name-based `Effect::OpenPopup` entry point. Dismiss
    /// tears the buffer down (`dismiss_stale_popup_registry`), so the next open
    /// is a fresh buffer whose owning mode re-projects on activation.
    #[test]
    fn open_popup_named_ensures_help_buffer_and_steals_focus() {
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::empty());

        editor.open_popup_named(
            "*ai-permission*",
            "ai-permission-mode",
            crate::popup::PopupPlacement::Centered,
            crate::popup::PopupFocus::Steal,
        );

        let id = editor.popup_buffer.expect("popup opened");
        assert_eq!(
            editor.buffers.kind_of(id),
            Some(BufferKind::Help),
            "popup buffer renders via the BufferData::Help path"
        );
        assert_eq!(editor.active_buffer, BufferKind::Help, "Steal focuses it");

        editor.dismiss_popup();
        assert_eq!(editor.popup_buffer, None, "dismiss clears the popup");
        assert_eq!(
            editor.buffers.kind_of(id),
            None,
            "dismiss tears the popup buffer down — next open is fresh"
        );
    }

    /// D.8.e: first `:diffthis` creates an N=1 dormant
    /// session keyed under the active buffer and sets
    /// `diffthis_group`. No pane group / fillers yet — the
    /// session has no peer to diff against until a second
    /// `:diffthis` extends it.
    #[test]
    fn diffthis_first_call_creates_dormant_singleton_session() {
        let mut editor = crate::editor::Editor::default();
        let (active_pane, active_buffer, _, _) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);

        editor.do_diffthis();

        assert_eq!(editor.diffthis_group, Some(active_buffer));
        assert_eq!(editor.diffthis_members.len(), 1);
        assert_eq!(editor.diffthis_members[0].pane, active_pane);
        assert_eq!(editor.diffthis_members[0].buffer, active_buffer);
        // Dormant session registered (arity 1, no peer).
        let session = editor
            .diff_subsystem
            .lookup(active_buffer)
            .expect("dormant session keyed under active");
        assert_eq!(session.buffer_id(), active_buffer);
        // No pane group + no fillers at arity 1.
        assert!(editor.pane_groups.is_empty());
        assert_eq!(
            editor.virtual_row_providers.snapshot(active_buffer).len(),
            0,
            "no filler provider registered for an N=1 dormant session"
        );
    }

    /// D.8.e: running `:diffthis` twice in the same pane
    /// removes the buffer from the group, which drops the
    /// arity from 1 to 0 and auto-drops the session. The
    /// editor's `diffthis_group` clears back to `None`.
    #[test]
    fn diffthis_same_pane_twice_removes_and_auto_drops() {
        let mut editor = crate::editor::Editor::default();
        let (_active_pane, active_buffer, _, _) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);

        editor.do_diffthis();
        assert_eq!(editor.diffthis_group, Some(active_buffer));
        editor.do_diffthis();
        assert!(editor.diffthis_group.is_none());
        assert!(editor.diffthis_members.is_empty());
        assert!(
            editor.diff_subsystem.lookup(active_buffer).is_none(),
            "session auto-drops at arity 0"
        );
    }

    /// D.8.e: first `:diffthis` in pane A creates an N=1
    /// dormant session; second `:diffthis` in pane B extends
    /// it to N=2. Session identity preserved (still keyed
    /// under A's buffer). Pane group + filler providers wire
    /// in at the arity-2 transition.
    #[tokio::test]
    async fn diffthis_second_pane_extends_to_arity_two() {
        let mut editor = crate::editor::Editor::default();
        let (_, active_buffer, _, other_buffer) = vsplit_two_buffers(&mut editor);

        // First diffthis in pane 0.
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        let primary = editor.diffthis_group.expect("group set");
        assert_eq!(primary, active_buffer);

        // Second diffthis in pane 1.
        editor.pane_tree.set_active(1);
        editor.do_diffthis();

        // diffthis_group unchanged — D.8.e preserves
        // session identity across the arity-1→2 transition.
        assert_eq!(editor.diffthis_group, Some(active_buffer));
        assert_eq!(editor.diffthis_members.len(), 2);

        // Descriptor now has 2 sources / participants.
        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(active_buffer)
            .expect("descriptor present");
        assert_eq!(descriptor.arity(), 2);
        assert!(descriptor.participants.contains(&active_buffer));
        assert!(descriptor.participants.contains(&other_buffer));

        // Pane group + fillers wire in at arity 2.
        let session = editor
            .diff_subsystem
            .lookup(active_buffer)
            .expect("session alive");
        let pg_id = session
            .pane_group_id()
            .expect("pane group bound at arity 2");
        let pg = editor
            .pane_groups
            .iter()
            .find(|g| g.id == pg_id)
            .expect("pane group present");
        assert_eq!(pg.members.len(), 2);

        // Filler providers registered for both sides.
        assert_eq!(
            editor.virtual_row_providers.snapshot(active_buffer).len(),
            1,
            "slot-0 filler registered under first :diffthis buffer"
        );
        assert_eq!(
            editor.virtual_row_providers.snapshot(other_buffer).len(),
            1,
            "slot-1 filler registered under second :diffthis buffer"
        );
    }

    /// D.8.e: third `:diffthis` extends the diffthis group to
    /// arity 3 — the engine's `three_way` path. Pane group is
    /// drop-and-recreated with a `three_pane` row mapper;
    /// fillers re-registered for all three members.
    #[tokio::test]
    async fn diffthis_third_pane_extends_to_arity_three() {
        let mut editor = crate::editor::Editor::default();
        let (buf0, buf1, buf2) = vsplit_three_buffers(&mut editor);

        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        let pg_before_third = editor
            .diff_subsystem
            .lookup(buf0)
            .and_then(|s| s.pane_group_id())
            .expect("pane group bound after arity-2");

        editor.pane_tree.set_active(2);
        editor.do_diffthis();

        assert_eq!(editor.diffthis_group, Some(buf0));
        assert_eq!(editor.diffthis_members.len(), 3);
        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(buf0)
            .expect("descriptor present");
        assert_eq!(descriptor.arity(), 3);
        for b in [buf0, buf1, buf2] {
            assert!(
                descriptor.participants.contains(&b),
                "{:?} should be a participant",
                b
            );
        }

        // Pane group was drop-and-recreated — fresh id.
        let pg_after_third = editor
            .diff_subsystem
            .lookup(buf0)
            .and_then(|s| s.pane_group_id())
            .expect("pane group re-bound at arity-3");
        assert_ne!(
            pg_before_third, pg_after_third,
            "arity-3 rebuild should produce a fresh pane group id"
        );
        let pg = editor
            .pane_groups
            .iter()
            .find(|g| g.id == pg_after_third)
            .expect("arity-3 pane group present");
        assert_eq!(pg.members.len(), 3);

        // Filler providers registered for all three members.
        for b in [buf0, buf1, buf2] {
            assert_eq!(
                editor.virtual_row_providers.snapshot(b).len(),
                1,
                "{:?} should have one filler provider",
                b
            );
        }
    }

    /// D.8.e: arity-4 cap. After the diffthis group reaches
    /// arity 3, a fourth `:diffthis` is rejected via
    /// [`MembershipError::EngineRejected`] (engine's
    /// [`DiffEngineError::Unsupported`]). The session and
    /// members are left untouched — atomic rejection.
    #[tokio::test]
    async fn diffthis_fourth_pane_rejected_at_engine_cap() {
        let mut editor = crate::editor::Editor::default();
        // Build a 3-pane layout, fill to arity 3, then split a
        // fourth pane and try to diffthis it.
        let (buf0, buf1, buf2) = vsplit_three_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        editor.pane_tree.set_active(2);
        editor.do_diffthis();
        assert_eq!(editor.diffthis_members.len(), 3);
        let pg_before_reject = editor
            .diff_subsystem
            .lookup(buf0)
            .and_then(|s| s.pane_group_id())
            .expect("pane group bound at arity 3");

        // Fourth pane.
        use lattice_core::ui::pane::SplitOrientation;
        editor.pane_tree.set_active(2);
        editor.pane_tree.split_active(SplitOrientation::Vertical);
        let buf3 = lattice_core::BufferId(101);
        let new_leaf_idx = editor.pane_tree.leaves().len() - 1;
        editor.pane_tree.leaves_mut()[new_leaf_idx].buffer_id = buf3;
        editor.pane_tree.set_active(new_leaf_idx);

        editor.do_diffthis();

        // Reject message surfaced.
        let msg = editor.last_message.as_ref().expect("error msg");
        assert!(
            msg.text.contains("up to 3 participants"),
            "expected engine-cap reject, got: {}",
            msg.text
        );

        // State unchanged from the arity-3 snapshot.
        assert_eq!(editor.diffthis_members.len(), 3);
        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(buf0)
            .expect("descriptor still present");
        assert_eq!(descriptor.arity(), 3);
        for b in [buf0, buf1, buf2] {
            assert!(descriptor.participants.contains(&b));
        }
        assert!(
            !descriptor.participants.contains(&buf3),
            "rejected participant must not appear in descriptor"
        );
        let pg_after_reject = editor
            .diff_subsystem
            .lookup(buf0)
            .and_then(|s| s.pane_group_id())
            .expect("pane group still bound");
        assert_eq!(
            pg_before_reject, pg_after_reject,
            "rejected add must not rebuild the pane group"
        );
    }

    /// D.8.e: `:diffthis` on a participant of an arity-3 group
    /// shrinks the group back to arity 2. The pane group is
    /// drop-and-recreated with a 2-pane mapper; the removed
    /// buffer's filler provider is unregistered.
    #[tokio::test]
    async fn diffthis_toggle_off_from_arity_three_shrinks_to_two() {
        let mut editor = crate::editor::Editor::default();
        let (buf0, buf1, buf2) = vsplit_three_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        editor.pane_tree.set_active(2);
        editor.do_diffthis();
        assert_eq!(editor.diffthis_members.len(), 3);

        // Toggle off the third pane.
        editor.pane_tree.set_active(2);
        editor.do_diffthis();

        assert_eq!(editor.diffthis_group, Some(buf0));
        assert_eq!(editor.diffthis_members.len(), 2);
        assert!(
            editor.diffthis_members.iter().all(|m| m.buffer != buf2),
            "third member removed"
        );

        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(buf0)
            .expect("descriptor present");
        assert_eq!(descriptor.arity(), 2);
        assert!(!descriptor.participants.contains(&buf2));

        // Pane group at arity 2 still bound; arity-2 fillers
        // for buf0 + buf1 present, buf2's filler gone.
        let pg_id = editor
            .diff_subsystem
            .lookup(buf0)
            .and_then(|s| s.pane_group_id())
            .expect("pane group re-bound at arity 2");
        let pg = editor
            .pane_groups
            .iter()
            .find(|g| g.id == pg_id)
            .expect("arity-2 pane group present");
        assert_eq!(pg.members.len(), 2);
        assert_eq!(editor.virtual_row_providers.snapshot(buf0).len(), 1);
        assert_eq!(editor.virtual_row_providers.snapshot(buf1).len(), 1);
        assert_eq!(
            editor.virtual_row_providers.snapshot(buf2).len(),
            0,
            "removed participant's filler unregistered"
        );
    }

    /// The active buffer already has a non-diffthis session
    /// (e.g. inline `:diff` or `:diffsplit`) → `:diffthis`
    /// errors. Defends users from accidentally double-binding
    /// a buffer across diff session kinds.
    #[test]
    fn diffthis_rejects_when_active_buffer_has_session() {
        let mut editor = crate::editor::Editor::default();
        let (_, active_buffer, _, _) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);

        // Pre-register a stub session against the active
        // buffer. `register` (the sources-less path) is fine
        // for this lifecycle check.
        editor
            .diff_subsystem
            .register(active_buffer, lattice_diff::DiffAlgorithm::Histogram);

        editor.do_diffthis();
        let msg = editor.last_message.as_ref().expect("error msg");
        assert!(
            msg.text.contains("already has an active diff session"),
            "expected reject message, got: {}",
            msg.text
        );
        assert!(editor.diffthis_group.is_none());
        assert!(editor.diffthis_members.is_empty());
    }

    /// `:diffthis` on a non-Document active pane (file tree /
    /// help / etc.) errors without touching diffthis state.
    #[test]
    fn diffthis_rejects_non_document_active_pane() {
        let mut editor = crate::editor::Editor::default();
        // Flip the active leaf's kind. Buffer-kind dispatch
        // happens before the toggle logic.
        editor.pane_tree.leaves_mut()[0].buffer = lattice_core::BufferKind::FileTree;

        editor.do_diffthis();
        let msg = editor.last_message.as_ref().expect("error msg");
        assert!(
            msg.text.contains("not a document"),
            "expected reject message, got: {}",
            msg.text
        );
        assert!(editor.diffthis_group.is_none());
        assert!(editor.diffthis_members.is_empty());
    }

    /// D.8.f: `:diffoff` from a diffthis-group member at
    /// arity 2 removes that buffer and shrinks the group to
    /// arity 1 (dormant). The pane group + fillers are torn
    /// down; the session lingers as a dormant N=1 holder so
    /// a subsequent `:diffthis` on another buffer can extend
    /// it again (vim's `:set nodiff` on one window doesn't
    /// un-set the others). `diffthis_group` stays `Some(...)`.
    #[tokio::test]
    async fn diffoff_from_diffthis_member_shrinks_to_arity_one_dormant() {
        let mut editor = crate::editor::Editor::default();
        let (_, baseline_buffer, _, current_buffer) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        assert!(
            editor.diff_subsystem.lookup(baseline_buffer).is_some(),
            "session keyed under first :diffthis buffer"
        );

        // `:diffoff` from the second-added pane.
        editor.pane_tree.set_active(1);
        editor.document_buffer_id = current_buffer;
        editor.do_diff_off(false);

        // Group survives as N=1 dormant (still keyed under
        // baseline_buffer); pane group + fillers gone.
        assert_eq!(editor.diffthis_group, Some(baseline_buffer));
        assert_eq!(editor.diffthis_members.len(), 1);
        assert_eq!(editor.diffthis_members[0].buffer, baseline_buffer);
        assert!(
            editor.diff_subsystem.lookup(baseline_buffer).is_some(),
            "dormant N=1 session lingers under the surviving primary"
        );
        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(baseline_buffer)
            .expect("descriptor present");
        assert_eq!(descriptor.arity(), 1);
        assert!(!descriptor.participants.contains(&current_buffer));
        assert!(editor.pane_groups.is_empty(), "pane group dropped");
        assert!(
            editor
                .virtual_row_providers
                .snapshot(current_buffer)
                .is_empty(),
            "removed-side filler unregistered"
        );
        assert!(
            editor
                .virtual_row_providers
                .snapshot(baseline_buffer)
                .is_empty(),
            "survivor filler unregistered at dormant arity 1"
        );
    }

    /// D.8.f: `:diffoff!` (force) on a diffthis-group member
    /// bypasses the membership-API shrink and cascades a
    /// full session teardown — the D.6.g semantic is
    /// preserved. After bang from either side, the session,
    /// pane group, and group state are all gone.
    #[tokio::test]
    async fn diffoff_bang_from_diffthis_member_full_teardown() {
        let mut editor = crate::editor::Editor::default();
        let (_, baseline_buffer, _, current_buffer) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();

        // Bang from the second-added pane.
        editor.pane_tree.set_active(1);
        editor.document_buffer_id = current_buffer;
        editor.do_diff_off(true);

        assert!(editor.diff_subsystem.is_empty(), "session dropped");
        assert!(editor.pane_groups.is_empty(), "pane group dropped");
        assert!(
            editor
                .virtual_row_providers
                .snapshot(baseline_buffer)
                .is_empty(),
            "baseline filler unregistered"
        );
        assert!(
            editor
                .virtual_row_providers
                .snapshot(current_buffer)
                .is_empty(),
            "current filler unregistered"
        );
    }

    // ─────────────────────────────────────────────────────────
    // D.5.a: diff-mode lifecycle end-to-end. Verifies the full
    // path:
    //   `:diffthis` / `:diff` → `register_with_sources` → bridge
    //     queue → `apply_pending_diff_mode_changes` → `ActiveModes`.
    // Plus the symmetric teardown path. The pure-bridge tests
    // live in `crate::diff::mode::tests`; these tests assert the
    // integration is wired correctly.
    // ─────────────────────────────────────────────────────────

    fn diff_mode_active_on(editor: &crate::editor::Editor, buffer: lattice_core::BufferId) -> bool {
        editor
            .active_modes
            .get(&buffer)
            .map(|am| am.has_minor(crate::diff::mode::DiffMode::mode_id()))
            .unwrap_or(false)
    }

    /// `Editor::default()` constructs an empty `ModeRegistry`;
    /// the tests below need `diff-mode` registered against it
    /// so the dispatch tail's
    /// [`Editor::apply_pending_diff_mode_changes`] toggles
    /// land in `ActiveModes`. Boot wires this via
    /// `register_diff_modes` — in tests we replace the
    /// default-empty `Arc<ModeRegistry>` before any session
    /// opens.
    fn editor_with_diff_mode_registered() -> crate::editor::Editor {
        let editor = crate::editor::Editor::default();
        let mut registry = lattice_mode::ModeRegistry::new();
        crate::diff::mode::register_diff_modes(&mut registry);
        editor.mode_registry.store(std::sync::Arc::new(registry));
        editor
    }

    // ── MA.2: minor-activation resolver wiring ──────────────────
    // The decision logic (ActivationPolicy::admits kind-gate,
    // auto_activatable_minors) is unit-tested in lattice-mode. These
    // tests assert the host glue: Event::MajorEntered → kind lookup →
    // auto_activatable_minors → activate_mode_by_id.

    /// A marker minor mode with a configurable ActivationPolicy.
    struct PolicyMinor {
        id: lattice_mode::ModeId,
        policy: lattice_mode::ActivationPolicy,
    }
    impl lattice_mode::Mode for PolicyMinor {
        type Guard = ();
        fn id(&self) -> lattice_mode::ModeId {
            self.id
        }
        fn kind(&self) -> lattice_mode::ModeKind {
            lattice_mode::ModeKind::Minor
        }
        fn activation_policy(&self) -> lattice_mode::ActivationPolicy {
            self.policy.clone()
        }
        fn on_activate(
            &self,
            _ctx: lattice_mode::ModeContext,
        ) -> lattice_mode::LifecycleFuture<'_, ()> {
            Box::pin(async { Ok(()) })
        }
    }

    fn minor_active_on(
        editor: &crate::editor::Editor,
        buffer: lattice_core::BufferId,
        mode: lattice_mode::ModeId,
    ) -> bool {
        editor
            .active_modes
            .get(&buffer)
            .map(|am| am.has_minor(mode))
            .unwrap_or(false)
    }

    #[tokio::test]
    async fn major_entered_resolver_activates_global_minor_on_document() {
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::from_text("x\n"));
        let doc = editor.document_buffer_id;
        // Sanity: the boot buffer is a real document buffer (the
        // resolver's Global gate keys on this).
        assert_eq!(
            editor.buffers.kind_of(doc),
            Some(lattice_core::BufferKind::Document)
        );

        let global_id = lattice_mode::ModeId::new("test-global-minor-mode");
        let rusty_id = lattice_mode::ModeId::new("test-rust-minor-mode");
        let mut registry = lattice_mode::ModeRegistry::new();
        registry
            .register(PolicyMinor {
                id: global_id,
                policy: lattice_mode::ActivationPolicy::Global,
            })
            .unwrap();
        registry
            .register(PolicyMinor {
                id: rusty_id,
                policy: lattice_mode::ActivationPolicy::Majors(vec![lattice_mode::ModeId::new(
                    "rust-mode",
                )]),
            })
            .unwrap();
        editor.mode_registry.store(std::sync::Arc::new(registry));

        // Clear any MajorEntered the boot path already queued, so we
        // assert against exactly the event we publish.
        let _ = editor.drain_minor_activation();

        // A document enters its (text) major.
        let proto = lattice_protocol::ids::BufferId::new(doc.0 as u64);
        editor
            .event_bus
            .publish(lattice_protocol::Event::MajorEntered {
                buffer: proto,
                major: "text-mode".into(),
            });
        let _ = editor.drain_minor_activation();

        assert!(
            minor_active_on(&editor, doc, global_id),
            "Global minor must auto-activate on a document buffer"
        );
        assert!(
            !minor_active_on(&editor, doc, rusty_id),
            "a Majors([rust-mode]) minor must NOT activate under text-mode"
        );
    }

    /// SN.3a: the real `snippet-mode` (Global) auto-activates on a
    /// document via the resolver, and its `implies`
    /// `snippet-completion-mode` (the source provider) rides the
    /// gate — proving the source reaches the buffer even though it
    /// was dropped from the language-blind
    /// `auto_activated_minors_for_buffer_kind` list.
    #[tokio::test]
    async fn major_entered_resolver_activates_snippet_mode_and_implied_source() {
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::from_text("x\n"));
        let doc = editor.document_buffer_id;
        assert_eq!(
            editor.buffers.kind_of(doc),
            Some(lattice_core::BufferKind::Document)
        );
        // Clear boot-queued events, then publish a clean MajorEntered.
        let _ = editor.drain_minor_activation();
        let proto = lattice_protocol::ids::BufferId::new(doc.0 as u64);
        editor
            .event_bus
            .publish(lattice_protocol::Event::MajorEntered {
                buffer: proto,
                major: "text-mode".into(),
            });
        let _ = editor.drain_minor_activation();

        assert!(
            minor_active_on(&editor, doc, lattice_snippet::SnippetMode::mode_id()),
            "snippet-mode (Global) auto-activates on a document"
        );
        assert!(
            minor_active_on(
                &editor,
                doc,
                lattice_snippet::SnippetCompletionMode::mode_id()
            ),
            "implied snippet-completion-mode rides snippet-mode's gate"
        );
    }

    /// SN.3b: `:set snippet.activation=...` (and `snippet.languages`)
    /// re-folds the shared policy cell the `snippet-mode` gate reads.
    /// The resolver reads that cell live (proven in
    /// `lattice_snippet::modes` tests + `auto_activatable_minors`),
    /// so this exercises the host's fold seam end-to-end:
    /// `do_set` → `apply_option_cascade` → folded `ActivationPolicy`.
    #[tokio::test]
    async fn set_snippet_activation_refolds_the_policy_cell() {
        use lattice_mode::{ActivationPolicy, ModeId};
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::from_text("x\n"));
        // Boot default (`snippet.activation = global`) → Global.
        assert_eq!(
            **editor.snippet_activation_policy.load(),
            ActivationPolicy::Global,
            "boot folds the default `global` to Global"
        );

        let _ = editor.do_set("snippet.activation=off");
        assert_eq!(
            **editor.snippet_activation_policy.load(),
            ActivationPolicy::Manual,
            "`off` folds to Manual (never auto-activate)"
        );

        // `supported-languages` + a language list → Majors([<lang>-mode]).
        let _ = editor.do_set("snippet.languages=rust,python");
        let _ = editor.do_set("snippet.activation=supported-languages");
        assert_eq!(
            **editor.snippet_activation_policy.load(),
            ActivationPolicy::Majors(vec![ModeId::new("rust-mode"), ModeId::new("python-mode")]),
            "`supported-languages` maps the language list to `<lang>-mode` majors"
        );

        // Editing only the language list re-folds too (same arm).
        let _ = editor.do_set("snippet.languages=rust");
        assert_eq!(
            **editor.snippet_activation_policy.load(),
            ActivationPolicy::Majors(vec![ModeId::new("rust-mode")]),
            "editing `snippet.languages` alone re-folds under the active mode"
        );

        // Back to global clears the language gating.
        let _ = editor.do_set("snippet.activation=global");
        assert_eq!(
            **editor.snippet_activation_policy.load(),
            ActivationPolicy::Global,
        );
    }

    /// Inline session activates diff-mode on the *current*
    /// buffer only — the file-on-disk baseline has no live
    /// buffer to mark.
    #[tokio::test]
    async fn inline_session_activates_diff_mode_on_current_only() {
        let mut editor = editor_with_diff_mode_registered();
        let primary = editor.document_buffer_id;
        // Inline session via the no-pane-group construction so
        // we exercise the same `register_with_sources` path
        // `do_diff_open` uses, without depending on a real
        // file. participants = [primary].
        let provider_text: std::sync::Arc<dyn crate::diff::subsystem::BufferTextProvider> =
            std::sync::Arc::new(crate::diff::subsystem::BufferRegistryTextProvider::new(
                editor.buffers.clone(),
            ));
        let descriptor = crate::diff::subsystem::DiffDescriptor {
            sources: vec![
                std::sync::Arc::new(crate::diff::subsystem::StaticSource::new(ropey::Rope::new())),
                std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                    provider_text,
                    primary,
                )),
            ],
            watch: vec![primary],
            participants: vec![primary],
        };
        editor.diff_subsystem.register_with_sources(
            primary,
            lattice_diff::DiffAlgorithm::Histogram,
            descriptor,
        );

        editor.apply_pending_diff_mode_changes();
        assert!(diff_mode_active_on(&editor, primary));
    }

    /// Two-pane `:diffthis` activates diff-mode on **both**
    /// participants so `do`/`dp` chord dispatch (D.5.b/c) works
    /// from either pane.
    #[tokio::test]
    async fn diffthis_activates_diff_mode_on_both_panes() {
        let mut editor = editor_with_diff_mode_registered();
        let (_, baseline_buffer, _, current_buffer) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();

        editor.apply_pending_diff_mode_changes();
        assert!(
            diff_mode_active_on(&editor, baseline_buffer),
            "baseline pane should have diff-mode active"
        );
        assert!(
            diff_mode_active_on(&editor, current_buffer),
            "current pane should have diff-mode active"
        );
    }

    /// D.8.f: `:diffoff` from a diffthis-group member clears
    /// diff-mode on the removed buffer only — the surviving
    /// participant stays in the (now dormant N=1) group and
    /// retains diff-mode, mirroring vim's `:set nodiff` on
    /// one window (the other still has `:set diff`). The
    /// bang form (`:diffoff!`) is the full-teardown path and
    /// is covered by `diffoff_bang_from_diffthis_member_full_teardown`.
    #[tokio::test]
    async fn diffoff_clears_diff_mode_only_on_removed_member() {
        let mut editor = editor_with_diff_mode_registered();
        let (_, baseline_buffer, _, current_buffer) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        editor.apply_pending_diff_mode_changes();
        assert!(diff_mode_active_on(&editor, baseline_buffer));
        assert!(diff_mode_active_on(&editor, current_buffer));

        // `:diffoff` from the second-added pane — shrinks
        // the group to arity 1 dormant.
        editor.pane_tree.set_active(1);
        editor.document_buffer_id = current_buffer;
        editor.do_diff_off(false);
        editor.apply_pending_diff_mode_changes();

        assert!(
            !diff_mode_active_on(&editor, current_buffer),
            "removed member's diff-mode cleared"
        );
        assert!(
            diff_mode_active_on(&editor, baseline_buffer),
            "surviving member keeps diff-mode (dormant N=1)"
        );
    }

    /// Doc-close auto-drop (`note_buffer_closed` →
    /// `drop_session`) deactivates diff-mode on the surviving
    /// peer. The bridge queue must drain at the next dispatch
    /// tick — simulated by calling
    /// `apply_pending_diff_mode_changes` directly.
    ///
    /// D.8.e: closing the **primary** participant
    /// (`baseline_buffer`, the first `:diffthis`) drops the
    /// session entirely. Closing a secondary watcher is
    /// covered by the per-participant tear-down work in D.8.f.
    #[tokio::test]
    async fn doc_close_auto_drop_clears_diff_mode_on_peer() {
        let mut editor = editor_with_diff_mode_registered();
        let (_, baseline_buffer, _, current_buffer) = vsplit_two_buffers(&mut editor);
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        editor.apply_pending_diff_mode_changes();
        assert!(diff_mode_active_on(&editor, current_buffer));

        // Simulate the bus-driven auto-drop the
        // `DocumentClosed` event would fire — closing the
        // primary participant drops the whole session.
        editor.diff_subsystem.note_buffer_closed(baseline_buffer);
        editor.apply_pending_diff_mode_changes();

        assert!(
            !diff_mode_active_on(&editor, baseline_buffer),
            "baseline diff-mode cleared by auto-drop"
        );
        assert!(
            !diff_mode_active_on(&editor, current_buffer),
            "current diff-mode cleared by auto-drop"
        );
    }

    /// Two simultaneous independent sessions
    /// (file1↔file2, file3↔file4) — diff-mode lights up on each
    /// pair independently; closing one leaves the other
    /// untouched.
    #[tokio::test]
    async fn two_independent_sessions_have_independent_diff_mode_state() {
        let mut editor = editor_with_diff_mode_registered();
        let provider_text: std::sync::Arc<dyn crate::diff::subsystem::BufferTextProvider> =
            std::sync::Arc::new(crate::diff::subsystem::BufferRegistryTextProvider::new(
                editor.buffers.clone(),
            ));
        let mk = |baseline: lattice_core::BufferId, current: lattice_core::BufferId| {
            crate::diff::subsystem::DiffDescriptor {
                sources: vec![
                    std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                        std::sync::Arc::clone(&provider_text),
                        baseline,
                    )),
                    std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                        std::sync::Arc::clone(&provider_text),
                        current,
                    )),
                ],
                watch: vec![baseline, current],
                participants: vec![baseline, current],
            }
        };
        let f1 = lattice_core::BufferId(101);
        let f2 = lattice_core::BufferId(102);
        let f3 = lattice_core::BufferId(103);
        let f4 = lattice_core::BufferId(104);
        editor.diff_subsystem.register_with_sources(
            f2,
            lattice_diff::DiffAlgorithm::Histogram,
            mk(f1, f2),
        );
        editor.diff_subsystem.register_with_sources(
            f4,
            lattice_diff::DiffAlgorithm::Histogram,
            mk(f3, f4),
        );
        editor.apply_pending_diff_mode_changes();
        for b in [f1, f2, f3, f4] {
            assert!(
                diff_mode_active_on(&editor, b),
                "buffer {b:?} should have diff-mode active"
            );
        }

        // Close session A (f2). Session B (f3↔f4) untouched.
        editor.diff_subsystem.drop_session(f2);
        editor.apply_pending_diff_mode_changes();
        assert!(!diff_mode_active_on(&editor, f1), "f1 cleared with A");
        assert!(!diff_mode_active_on(&editor, f2), "f2 cleared with A");
        assert!(diff_mode_active_on(&editor, f3), "f3 still in B");
        assert!(diff_mode_active_on(&editor, f4), "f4 still in B");
    }

    /// Refcount correctness: the same buffer participating in
    /// two simultaneous sessions stays diff-mode-active until
    /// the *last* session closes. Regression guard against the
    /// naive "session opens → on / session closes → off" shape.
    #[tokio::test]
    async fn shared_buffer_in_two_sessions_keeps_diff_mode_until_last_close() {
        let mut editor = editor_with_diff_mode_registered();
        let provider_text: std::sync::Arc<dyn crate::diff::subsystem::BufferTextProvider> =
            std::sync::Arc::new(crate::diff::subsystem::BufferRegistryTextProvider::new(
                editor.buffers.clone(),
            ));
        let shared = lattice_core::BufferId(201);
        let peer_a = lattice_core::BufferId(202);
        let peer_b = lattice_core::BufferId(203);
        let mk = |baseline: lattice_core::BufferId, current: lattice_core::BufferId| {
            crate::diff::subsystem::DiffDescriptor {
                sources: vec![
                    std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                        std::sync::Arc::clone(&provider_text),
                        baseline,
                    )),
                    std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                        std::sync::Arc::clone(&provider_text),
                        current,
                    )),
                ],
                watch: vec![baseline, current],
                participants: vec![baseline, current],
            }
        };
        // Session A: shared ↔ peer_a (primary = peer_a).
        editor.diff_subsystem.register_with_sources(
            peer_a,
            lattice_diff::DiffAlgorithm::Histogram,
            mk(shared, peer_a),
        );
        // Session B: shared ↔ peer_b (primary = peer_b).
        editor.diff_subsystem.register_with_sources(
            peer_b,
            lattice_diff::DiffAlgorithm::Histogram,
            mk(shared, peer_b),
        );
        editor.apply_pending_diff_mode_changes();
        assert!(diff_mode_active_on(&editor, shared));
        assert!(diff_mode_active_on(&editor, peer_a));
        assert!(diff_mode_active_on(&editor, peer_b));
        assert_eq!(editor.diff_subsystem.mode_bridge().refcount(shared), 2);

        // Close A. shared must stay active (B still needs it).
        editor.diff_subsystem.drop_session(peer_a);
        editor.apply_pending_diff_mode_changes();
        assert!(
            diff_mode_active_on(&editor, shared),
            "shared must stay active while B holds it"
        );
        assert!(!diff_mode_active_on(&editor, peer_a));
        assert!(diff_mode_active_on(&editor, peer_b));
        assert_eq!(editor.diff_subsystem.mode_bridge().refcount(shared), 1);

        // Close B. shared now drops.
        editor.diff_subsystem.drop_session(peer_b);
        editor.apply_pending_diff_mode_changes();
        assert!(!diff_mode_active_on(&editor, shared));
        assert!(!diff_mode_active_on(&editor, peer_b));
        assert_eq!(editor.diff_subsystem.mode_bridge().refcount(shared), 0);
    }

    /// Scratch / unsaved buffers (no `Path`) work end-to-end —
    /// the diff layer takes no path dependency, so a two-pane
    /// diff between two scratch buffers activates diff-mode on
    /// both. Verifies the design's path-free commitment
    /// (architecture doc §3.4.1) survives the D.5.a wiring.
    #[tokio::test]
    async fn scratch_to_scratch_diff_activates_diff_mode_on_both() {
        let mut editor = editor_with_diff_mode_registered();
        let (_, baseline_buffer, _, current_buffer) = vsplit_two_buffers(&mut editor);
        // Neither buffer has a file path — the BufferRegistry
        // entries are absent; `BufferRegistryTextProvider`
        // returns empty ropes for missing buffers, which the
        // diff layer handles uniformly (all-Add baseline).
        editor.pane_tree.set_active(0);
        editor.do_diffthis();
        editor.pane_tree.set_active(1);
        editor.do_diffthis();
        editor.apply_pending_diff_mode_changes();
        assert!(diff_mode_active_on(&editor, baseline_buffer));
        assert!(diff_mode_active_on(&editor, current_buffer));
    }

    /// `DiffSubsystem::lookup_session_for` resolves a
    /// secondary buffer back to the session whose primary key
    /// differs. Direct unit test on the subsystem so the
    /// indirection contract is asserted independently of the
    /// `:diffthis` completion path.
    #[test]
    fn subsystem_lookup_session_for_resolves_secondary_to_primary() {
        let sub = crate::diff::subsystem::DiffSubsystem::new();
        let primary = lattice_core::BufferId(7);
        let secondary = lattice_core::BufferId(8);

        // Stand-in descriptor — sources empty (their snapshots
        // return empty ropes); what matters is the `watch`
        // list shape: `[primary, secondary]`.
        let provider_text: std::sync::Arc<dyn crate::diff::subsystem::BufferTextProvider> =
            std::sync::Arc::new(crate::diff::subsystem::BufferRegistryTextProvider::new(
                crate::buffer_registry::BufferRegistry::new(),
            ));
        let descriptor = crate::diff::subsystem::DiffDescriptor {
            sources: vec![
                std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                    std::sync::Arc::clone(&provider_text),
                    secondary,
                )),
                std::sync::Arc::new(crate::diff::subsystem::BufferSource::new(
                    std::sync::Arc::clone(&provider_text),
                    primary,
                )),
            ],
            watch: vec![primary, secondary],
            participants: vec![primary, secondary],
        };
        sub.register_with_sources(primary, lattice_diff::DiffAlgorithm::Histogram, descriptor);

        // Primary lookup works.
        let from_primary = sub
            .lookup_session_for(primary)
            .expect("primary resolves to its session");
        assert_eq!(from_primary.buffer_id(), primary);
        // Secondary lookup resolves through the index.
        let from_secondary = sub
            .lookup_session_for(secondary)
            .expect("secondary resolves to the same session");
        assert_eq!(from_secondary.buffer_id(), primary);
        assert!(std::sync::Arc::ptr_eq(&from_primary, &from_secondary));

        // After `drop_session(primary)`, the secondary entry
        // is scrubbed too — no zombie indirection.
        sub.drop_session(primary);
        assert!(sub.lookup_session_for(primary).is_none());
        assert!(sub.lookup_session_for(secondary).is_none());
    }

    // ── K.1.d: describe-key runtime registry section ──────────

    /// K.1.d: `:describe-key` includes a "Runtime registry"
    /// section listing minor-mode bindings with their active
    /// status. When the relevant mode is active on the active
    /// buffer, the binding shows `[active]`; otherwise
    /// `[inactive — mode not active on this buffer]`.
    /// Validates the visibility story the user cares about:
    /// `describe-key` answers "why doesn't `do` work here?"
    /// by surfacing the inactive mode.
    #[test]
    fn describe_key_runtime_registry_marks_inactive_minor_mode_bindings() {
        use crate::keymap_registry::PushLayerKind;
        use crate::keymap_trie::{BoundCommand, ChordPattern, KeymapLayer, KeymapTrie};
        use lattice_grammar::CommandInvocation;
        use lattice_grammar::SourceLocation;
        use lattice_mode::mode::ModeId;
        use lattice_protocol::ids::CommandId;
        use std::collections::HashMap;
        use std::sync::Arc;

        let editor = crate::editor::Editor::default();
        let diff_mode = ModeId::new("diff-mode");

        // Push diff-mode with `do` → CommandId(0xD1FF).
        let mut bindings = HashMap::new();
        let mut trie = KeymapTrie::new();
        trie.insert(
            &[
                ChordPattern::Literal(crate::chord::KeyChord::char('d')),
                ChordPattern::Literal(crate::chord::KeyChord::char('o')),
            ],
            Arc::new(BoundCommand::from_invocation(
                CommandInvocation::of(CommandId::new(0xD1FF)),
                SourceLocation::synthetic("test:diff-mode.do"),
                KeymapLayer::MinorMode(diff_mode),
            )),
        );
        bindings.insert(crate::keymap::BindingMode::Normal, trie);
        editor
            .keymap
            .push_layer(PushLayerKind::MinorMode(diff_mode), "diff-mode", bindings);

        // Active buffer does NOT have diff-mode active.
        let content = editor.build_describe_key_content("do");
        let body = content.lines().join("\n");
        // T12 format: binding is found (non-empty resolution) but
        // all layers are inactive on the current buffer.
        assert!(
            !body.contains("is not bound in any mode"),
            "describe-key must find the diff-mode registration, got:\n{body}"
        );
        assert!(
            body.contains("registered but not active"),
            "inactive minor-mode binding must show 'registered but not active', got:\n{body}"
        );
    }

    /// SN.3c.2b: `:describe-key` surfaces a binding's `fall_through`
    /// flag in the layer trace so the augment-and-continue behavior is
    /// introspectable (§5.11). Mirrors the inactive-minor test above:
    /// pushes a `fall_through` `<Esc>` binding on an (inactive) minor
    /// layer and asserts the trace tags it `fall-through`.
    #[test]
    fn describe_key_surfaces_fall_through_flag() {
        use crate::keymap_registry::PushLayerKind;
        use crate::keymap_trie::{BoundCommand, ChordPattern, KeymapLayer, KeymapTrie};
        use lattice_grammar::CommandInvocation;
        use lattice_grammar::SourceLocation;
        use lattice_mode::mode::ModeId;
        use lattice_protocol::ids::CommandId;
        use std::collections::HashMap;
        use std::sync::Arc;

        let editor = crate::editor::Editor::default();
        let snippet_mode = ModeId::new("active-snippet-mode");
        let esc = ChordPattern::Literal(crate::chord::KeyChord::special(
            crate::chord::SpecialKey::Esc,
        ));

        // Builtin (always-on) `<Esc>` → the native binding it would fall
        // through TO, so the trace has >1 layer and the "All layers"
        // block (which carries the fall-through tag) renders.
        editor.keymap.bind(
            KeymapLayer::Builtin,
            crate::keymap::BindingMode::Insert,
            std::slice::from_ref(&esc),
            CommandInvocation::of(CommandId::new(0xE17E)),
            SourceLocation::synthetic("test:builtin.esc"),
        );

        // Minor-layer `<Esc>` with `fall_through: true`.
        let mut bindings = HashMap::new();
        let mut trie = KeymapTrie::new();
        trie.insert(
            std::slice::from_ref(&esc),
            Arc::new(
                BoundCommand::from_invocation(
                    CommandInvocation::of(CommandId::new(0x5EFF)),
                    SourceLocation::synthetic("test:active-snippet.esc"),
                    KeymapLayer::MinorMode(snippet_mode),
                )
                .with_fall_through(true),
            ),
        );
        bindings.insert(crate::keymap::BindingMode::Insert, trie);
        editor.keymap.push_layer(
            PushLayerKind::MinorMode(snippet_mode),
            "active-snippet-mode",
            bindings,
        );

        let content = editor.build_describe_key_content("i_<Esc>");
        let body = content.lines().join("\n");
        assert!(
            body.contains("fall-through"),
            "describe-key must surface the fall_through flag, got:\n{body}"
        );
    }

    // ── D.4.d.3.b: :diffsplit <file> ──────────────────────────

    /// Write `contents` to a uniquely-named temp file and
    /// return the path. Caller is responsible for deletion
    /// (drop the returned `TempFilePath` to remove it).
    struct TempFilePath(std::path::PathBuf);
    impl Drop for TempFilePath {
        fn drop(&mut self) {
            let _ = std::fs::remove_file(&self.0);
        }
    }
    fn write_temp(contents: &str, tag: &str) -> TempFilePath {
        let mut path = std::env::temp_dir();
        // Cargo test nameserver: pid + tag keeps tests
        // running in parallel from colliding.
        path.push(format!(
            "lattice-diffsplit-{}-{}-{}.tmp",
            std::process::id(),
            tag,
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0),
        ));
        std::fs::write(&path, contents).expect("write temp file");
        TempFilePath(path)
    }

    /// `:diffsplit` rejects a non-Document active pane up-
    /// front — no split happens. Mirrors `diffthis_rejects_*`.
    #[test]
    fn diffsplit_rejects_non_document_active_pane() {
        let mut editor = crate::editor::Editor::default();
        editor.pane_tree.leaves_mut()[0].buffer = lattice_core::BufferKind::FileTree;
        let pane_count_before = editor.pane_tree.leaves().len();

        editor.do_diffsplit(std::path::PathBuf::from("/dev/null"), None);

        let msg = editor.last_message.as_ref().expect("error msg");
        assert!(
            msg.text.contains("not a document"),
            "expected reject message, got: {}",
            msg.text
        );
        assert_eq!(
            editor.pane_tree.leaves().len(),
            pane_count_before,
            "no split should happen on the reject path"
        );
    }

    /// `:diffsplit` rejects when the active buffer already
    /// participates in a session. Mirrors
    /// `diffthis_rejects_when_active_buffer_has_session`.
    #[test]
    fn diffsplit_rejects_when_active_buffer_has_session() {
        let mut editor = crate::editor::Editor::default();
        let active_buffer = editor.pane_tree.active().buffer_id;
        editor
            .diff_subsystem
            .register(active_buffer, lattice_diff::DiffAlgorithm::Histogram);
        let pane_count_before = editor.pane_tree.leaves().len();

        editor.do_diffsplit(std::path::PathBuf::from("/dev/null"), None);

        let msg = editor.last_message.as_ref().expect("error msg");
        assert!(
            msg.text.contains("already has an active diff session"),
            "expected reject message, got: {}",
            msg.text
        );
        assert_eq!(
            editor.pane_tree.leaves().len(),
            pane_count_before,
            "no split should happen on the reject path"
        );
    }

    /// Happy path: `:diffsplit <existing-file>` vsplits the
    /// pane, loads the file in the new pane, and registers a
    /// two-pane diff between the two leaves. Session, pane
    /// group, and both filler providers are in place at the
    /// end.
    ///
    /// Uses `Editor::boot` (not `Editor::default()`) because
    /// `do_edit`'s happy path consults the options cascade
    /// (`expandtab`, `tabstop`, …) which `default()` doesn't
    /// register. `#[tokio::test]` because boot + the
    /// completion path (`register_two_pane_diff` →
    /// `note_buffer_edited`) both arm tokio tasks.
    #[tokio::test]
    async fn diffsplit_opens_and_registers_two_pane_session() {
        let file = write_temp("baseline\ncontent\n", "happy");
        let document = lattice_core::Document::empty();
        let mut editor = crate::editor::Editor::boot(document);
        let baseline_buffer = editor.document_buffer_id;

        editor.do_diffsplit(file.0.clone(), None);

        // Two panes now: baseline + the newly-loaded file.
        assert_eq!(
            editor.pane_tree.leaves().len(),
            2,
            "vsplit must produce two panes on the happy path"
        );
        // The new pane (active after diffsplit per vim
        // parity) carries the loaded buffer.
        let current_buffer = editor.pane_tree.active().buffer_id;
        assert_ne!(
            current_buffer, baseline_buffer,
            "the new pane must show a different buffer"
        );
        // Session is registered keyed on the current side's
        // buffer, with the pane group bound.
        let session = editor
            .diff_subsystem
            .lookup(current_buffer)
            .expect("session registered under the new buffer");
        assert!(session.pane_group_id().is_some());
        // Either side resolves through the indirection map.
        assert!(
            editor
                .diff_subsystem
                .lookup_session_for(baseline_buffer)
                .is_some()
        );
        // Per-side filler providers registered scoped per
        // buffer (D.4.d.2.1.a).
        assert_eq!(
            editor.virtual_row_providers.snapshot(baseline_buffer).len(),
            1
        );
        assert_eq!(
            editor.virtual_row_providers.snapshot(current_buffer).len(),
            1
        );
    }

    /// `:e!` is a refresh, not a jump: reloading the current
    /// buffer from disk must keep the cursor where it was rather
    /// than snapping back to the top. (2026-06-03 regression —
    /// the M.0 slot-replacement model resets cursor/scroll to ZERO
    /// for the brand-new-file case; the reload branch restores
    /// them.)
    #[tokio::test]
    async fn edit_bang_preserves_cursor_position() {
        let file = write_temp(
            "line0\nline1\nline2\nline3\nline4\nline5\nline6\n",
            "ebang-keep",
        );
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::empty());
        editor.viewport_height = 5;
        // Open the file into the active slot.
        editor.do_edit(Some(file.0.clone()), false);
        // Park the cursor mid-buffer and scroll down a row.
        editor.cursor.line = 5;
        editor.cursor.byte = 3;
        editor.scroll = 2;
        // `:e!` — reload from disk (force, no path).
        editor.do_edit(None, true);
        assert_eq!(
            editor.cursor.line, 5,
            "`:e!` must keep the cursor on its line, not jump to the top"
        );
        assert_eq!(editor.cursor.byte, 3, "`:e!` must keep the cursor column");
        assert!(
            editor.scroll <= 5 && editor.cursor.line >= editor.scroll,
            "cursor must stay visible after reload (scroll={}, line={})",
            editor.scroll,
            editor.cursor.line
        );
    }

    /// `:e!` cursor restore is clamped to the freshly-loaded
    /// content: if the file shrank on disk, the cursor lands on
    /// the last addressable line instead of pointing past EOF.
    #[tokio::test]
    async fn edit_bang_clamps_cursor_when_file_shrank() {
        let file = write_temp("a\nb\nc\nd\ne\nf\ng\nh\n", "ebang-clamp");
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::empty());
        editor.viewport_height = 5;
        editor.do_edit(Some(file.0.clone()), false);
        editor.cursor.line = 7;
        // Shrink the file on disk, then reload.
        std::fs::write(&file.0, "x\ny\nz\n").expect("rewrite temp file");
        editor.do_edit(None, true);
        assert_eq!(
            editor.cursor.line, 2,
            "cursor must clamp to the last line of the shrunk file (0-indexed 2)"
        );
    }

    /// `:diffsplit <nonexistent-file>` fails inside `do_edit`
    /// and rolls the vsplit back, so the user isn't stranded
    /// in an empty pane. No session, no pane group.
    #[tokio::test]
    async fn diffsplit_rolls_back_split_on_open_failure() {
        let mut editor = crate::editor::Editor::default();
        let pane_count_before = editor.pane_tree.leaves().len();

        // Path that points at a directory — `do_edit` returns
        // `Directory(_)` which our handler routes to the
        // rollback branch. Cheaper than synthesising a path
        // guaranteed not to exist (which is racy across CI
        // environments).
        let bogus = std::env::temp_dir();
        editor.do_diffsplit(bogus, None);

        assert_eq!(
            editor.pane_tree.leaves().len(),
            pane_count_before,
            "failed open must collapse the new vsplit"
        );
        assert!(
            editor.diff_subsystem.is_empty(),
            "no session should be registered on the failure path"
        );
        assert!(
            editor.pane_groups.is_empty(),
            "no pane group should be registered on the failure path"
        );
    }

    // ──────────────────────────────────────────────────────
    // D.6.c (2026-05-31): :diffsplit base remote (3-way)
    // ──────────────────────────────────────────────────────
    //
    // Chained `:diffthis` N-way + the arity-agnostic
    // descriptor refactor are out of scope for D.6.c; that
    // lands in D.8 (see implementation ledger).

    /// `:diffsplit base remote` (two args) loads both files
    /// in new vsplits and registers a three-way merge
    /// session.
    #[tokio::test]
    async fn diffsplit_two_args_opens_three_way_session() {
        let base_file = write_temp("base-a\nbase-b\nbase-c\n", "d6c-base");
        let remote_file = write_temp("base-a\nREMOTE-b\nbase-c\n", "d6c-remote");
        let document = lattice_core::Document::empty();
        let mut editor = crate::editor::Editor::boot(document);
        let local_buffer = editor.document_buffer_id;
        let pane_count_before = editor.pane_tree.leaves().len();

        editor.do_diffsplit(base_file.0.clone(), Some(remote_file.0.clone()));

        // Two new vsplits opened.
        assert_eq!(
            editor.pane_tree.leaves().len(),
            pane_count_before + 2,
            "three-way diffsplit must open two new panes"
        );
        // Session registered under the local (original)
        // buffer.
        let session = editor
            .diff_subsystem
            .lookup(local_buffer)
            .expect("three-way session keyed under local buffer");
        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(local_buffer)
            .expect("descriptor present");
        assert!(descriptor.arity() == 3);
        assert_eq!(descriptor.participants.len(), 3);
        assert_eq!(descriptor.participants[1], local_buffer);
        // Pane group with three members.
        let pg_id = session.pane_group_id().expect("pane group bound");
        let pg = editor
            .pane_groups
            .iter()
            .find(|g| g.id == pg_id)
            .expect("pane group present");
        assert_eq!(pg.members.len(), 3);
        // Filler provider on every participant buffer.
        for b in &descriptor.participants {
            assert_eq!(
                editor.virtual_row_providers.snapshot(*b).len(),
                1,
                "filler registered on buffer {b:?}"
            );
        }
    }

    /// `:diffsplit base remote` rolls back both new vsplits
    /// when the second path (`remote`) fails to open. The
    /// user lands back on the original pane, no session
    /// or pane group leaks.
    #[tokio::test]
    async fn diffsplit_three_way_rolls_back_when_remote_open_fails() {
        let base_file = write_temp("base-a\n", "d6c-rollback-base");
        let document = lattice_core::Document::empty();
        let mut editor = crate::editor::Editor::boot(document);
        let pane_count_before = editor.pane_tree.leaves().len();

        // Remote path = a directory ⇒ `do_edit` returns
        // `Directory(_)` ⇒ the second `open_into_new_split`
        // call closes that pane; then our handler closes
        // the base pane too.
        let bogus_remote = std::env::temp_dir();
        editor.do_diffsplit(base_file.0.clone(), Some(bogus_remote));

        assert_eq!(
            editor.pane_tree.leaves().len(),
            pane_count_before,
            "both new vsplits must be rolled back on remote open failure"
        );
        assert!(editor.diff_subsystem.is_empty());
        assert!(editor.pane_groups.is_empty());
    }

    // ──────────────────────────────────────────────────────
    // D.6.h (2026-05-31): slice-plan canonical integration
    // test — `:diffput <bufnr>` resolves a three-way Conflict
    // by pushing the active side's content into the named
    // target. Full chain: `:diffsplit base remote` →
    // manually publish a Conflict hunk → `:diffput
    // <remote-bufnr>` → verify the remote buffer's
    // content was mutated to match local's.
    // ──────────────────────────────────────────────────────

    #[tokio::test]
    async fn three_way_diffput_resolves_conflict_by_pushing_active_into_target() {
        use lattice_diff::{Hunk, HunkIndex, HunkKind, LineRange};
        use smallvec::smallvec;

        // Set up three on-disk files. The user-visible
        // pane sequence after :diffsplit base remote will
        // be: [local (current pane), base (new pane 1),
        // remote (new pane 2)]. Diverging content per
        // side ensures a Conflict region.
        let base_file = write_temp("aaa\nbbb\nccc\n", "d6h-base");
        let remote_file = write_temp("aaa\nREMOTE-bbb\nccc\n", "d6h-remote");

        // Local document carries "LOCAL-bbb" on the same
        // row remote mutated → both modified row 1
        // differently → Conflict.
        let document = lattice_core::Document::from_text("aaa\nLOCAL-bbb\nccc\n");
        let mut editor = crate::editor::Editor::boot(document);
        let local_buffer = editor.document_buffer_id;

        editor.do_diffsplit(base_file.0.clone(), Some(remote_file.0.clone()));

        // After :diffsplit, the new panes have been opened.
        // The session is keyed under the local buffer.
        let descriptor = editor
            .diff_subsystem
            .lookup_descriptor(local_buffer)
            .expect("descriptor present after :diffsplit base remote");
        assert!(descriptor.arity() == 3);
        assert_eq!(descriptor.participants.len(), 3);
        assert_eq!(descriptor.participants[1], local_buffer, "local slot");
        let base_buffer = descriptor.participants[0];
        let remote_buffer = descriptor.participants[2];

        // Drain :diffsplit's auto-recompute so the manual
        // publish below is the published version when
        // `do_diff_put` reads `current_hunks()`.
        tokio::task::yield_now().await;
        tokio::time::sleep(std::time::Duration::from_millis(60)).await;

        // Manually publish a Conflict hunk on row 1 of
        // each side. (We can't easily depend on the real
        // engine producing exactly the shape we want
        // synchronously here — manual publish keeps the
        // test deterministic and isolated to the
        // dispatch path.)
        let session = editor
            .diff_subsystem
            .lookup(local_buffer)
            .expect("three-way session present");
        let rev = session.allocate_revision();
        session.publish(std::sync::Arc::new(HunkIndex {
            hunks: vec![Hunk {
                kind: HunkKind::Conflict,
                // [base, local, remote] — all touch row 1.
                ranges: smallvec![
                    LineRange::new(1, 2), // base: "bbb"
                    LineRange::new(1, 2), // local: "LOCAL-bbb"
                    LineRange::new(1, 2), // remote: "REMOTE-bbb"
                ],
                refine: Default::default(),
            }],
            algorithm: lattice_diff::DiffAlgorithm::Histogram,
            revision: rev,
        }));

        // Make the local pane active. After :diffsplit
        // the cursor was parked in the first new (base)
        // pane per vim parity — we need to switch back
        // to the local pane for `:diffput` to read the
        // right `document_buffer_id`.
        let local_pane_idx = editor
            .pane_tree
            .leaves()
            .iter()
            .position(|l| l.buffer_id == local_buffer)
            .expect("local pane still in tree");
        editor.pane_tree.set_active(local_pane_idx);
        editor.document_buffer_id = local_buffer;
        editor.cursor = lattice_protocol::position::Position::new(1, 0);

        // The canonical case: `:diffput <remote-bufnr>`
        // pushes local's content into remote's range.
        drive_diff_put(&mut editor, Some(remote_buffer));

        // Remote buffer's row 1 should now contain
        // local's "LOCAL-bbb" (replacing "REMOTE-bbb").
        let remote_handle = editor
            .buffers
            .document_handle(remote_buffer)
            .expect("remote handle present");
        let remote_text = remote_handle.snapshot().buffer.to_rope().to_string();
        assert_eq!(
            remote_text, "aaa\nLOCAL-bbb\nccc\n",
            "`:diffput {}` (remote bufnr) must push local's content into remote's range",
            remote_buffer.0
        );

        // Local + base unmodified — only the target was
        // mutated.
        let local_handle = editor
            .buffers
            .document_handle(local_buffer)
            .expect("local handle present");
        assert_eq!(
            local_handle.snapshot().buffer.to_rope().to_string(),
            "aaa\nLOCAL-bbb\nccc\n",
            "local buffer must remain unmutated by :diffput"
        );
        let base_handle = editor
            .buffers
            .document_handle(base_buffer)
            .expect("base handle present");
        assert_eq!(
            base_handle.snapshot().buffer.to_rope().to_string(),
            "aaa\nbbb\nccc\n",
            "base buffer must remain unmutated by :diffput"
        );
    }

    // ── K.3.5: missing-arg prompt API ──────────────────────────
    //
    // Regression coverage for the user-reported bug: the K.3.2
    // help-prefix keymap bindings invoked required-arg commands
    // with empty Args, which silently failed. Fix is the public
    // `arm_missing_arg_prompt` API + a short-circuit in
    // `run_invocation`. These tests pin the contract.

    #[test]
    fn arm_missing_arg_prompt_describe_key_arms_chord_capture() {
        // Calling the public API with the alias form should
        // arm the prompt with the alias's prefill and chord
        // auto-submit (the first arg is `ArgKind::Chord`).
        let document = lattice_core::Document::empty();
        let mut editor = Editor::boot(document);
        let armed = editor.arm_missing_arg_prompt("describe-key");
        assert!(armed, "arm_missing_arg_prompt must return true");
        assert_eq!(editor.command_line(), "describe-key ");
        assert!(matches!(editor.modal, lattice_grammar::ModalState::Command));
        assert!(
            editor.auto_submit_after_chord,
            "ArgKind::Chord must arm auto_submit_after_chord"
        );
    }

    #[test]
    fn arm_missing_arg_prompt_canonical_name_works() {
        // The canonical CommandRegistry name (with `ex:` prefix)
        // should also resolve. The armed cmdline always shows the
        // user-facing name with the `ex:` namespace prefix STRIPPED
        // (the prefix is internal and must never leak into the
        // command line the user types into) — so passing the
        // canonical form arms `describe-key `, identical to the alias.
        let document = lattice_core::Document::empty();
        let mut editor = Editor::boot(document);
        let armed = editor.arm_missing_arg_prompt("ex:describe-key");
        assert!(armed);
        assert_eq!(editor.command_line(), "describe-key ");
    }

    #[test]
    fn arm_missing_arg_prompt_returns_false_for_no_required_arg() {
        // `:help` and `:keymap` use `parse_no_args` — no required
        // arg, so the API returns false (caller should invoke
        // directly).
        let document = lattice_core::Document::empty();
        let mut editor = Editor::boot(document);
        let armed = editor.arm_missing_arg_prompt("help");
        assert!(!armed, "no-required-arg commands must return false");
        // Editor state untouched.
        assert!(matches!(editor.modal, lattice_grammar::ModalState::Normal));
    }

    #[test]
    fn arm_missing_arg_prompt_returns_false_for_unknown_command() {
        let document = lattice_core::Document::empty();
        let mut editor = Editor::boot(document);
        let armed = editor.arm_missing_arg_prompt("nonexistent-command-xyz");
        assert!(!armed);
        assert!(matches!(editor.modal, lattice_grammar::ModalState::Normal));
    }

    #[test]
    fn ex_line_operator_with_target_mutates_via_unified_dispatch() {
        // UD: an operator WITH a target invoked on the `:` line flows
        // through the same `dispatch_invocation` -> `execute_operator`
        // path as the keystroke `dw`, resolving the motion as a range and
        // committing the edit. Both the space-separated and canonical
        // forms parse to the same operator+motion invocation.
        for line in [
            "operator delete word-forward",
            "operator:delete motion:word-forward",
        ] {
            let document = lattice_core::Document::from_text("hello world\n");
            let mut editor = Editor::boot(document);
            editor.cursor = lattice_protocol::position::Position::new(0, 0);
            let mut out = DispatchOutcome::default();
            editor.execute_ex_line(line, &mut out);
            assert_eq!(
                editor.document.snapshot().buffer.as_string(),
                "world\n",
                "`:{line}` should delete the first word via the unified dispatch"
            );
        }
    }

    #[test]
    fn visual_colon_enters_command_line_with_range_prefill() {
        use lattice_protocol::position::Position;
        use lattice_protocol::selection::{Selection, SelectionSet};
        let document = lattice_core::Document::from_text("aaa\nbbb\nccc\nddd\n");
        let mut editor = Editor::boot(document);
        // Enter Visual linewise selecting lines 1..=2.
        editor.modal = ModalState::Visual(lattice_grammar::VisualKind::Linewise);
        editor.visual_anchor = Some(Position::new(1, 0));
        editor.cursor = Position::new(2, 0);
        editor.set_selections_blocking(SelectionSet::single(Selection {
            anchor: Position::new(1, 0),
            head: Position::new(2, 0),
            visual: Some(lattice_protocol::selection::VisualMode::Linewise),
        }));
        // `:` from Visual.
        let _ = editor.dispatch(Action::EnterCommandLine);
        assert!(
            matches!(editor.modal, ModalState::Command),
            "Visual `:` must enter Command mode, got {:?}",
            editor.modal
        );
        assert_eq!(
            editor.command_line(),
            "'<,'>",
            "Visual `:` prefills the visual range (vim's `:'<,'>`)"
        );
        let lv = editor.last_visual.as_ref().expect("last_visual captured");
        assert_eq!(lv.anchor, Position::new(1, 0));
        assert_eq!(lv.head, Position::new(2, 0));
        // The captured `last_visual` is what `'<` / `'>` and
        // `Range::Selection` resolve from (`resolve_grammar_range`
        // dispatch.rs ~13659; the narrow handler ~5396), so the typed
        // `:'<,'>narrow` / `:'<,'>...` now operates on the selection.
    }

    // ---- CB.1: clipboard yank-only sync (docs/dev/architecture/clipboard.md §5) ----

    /// `Editor::boot` registers a `FakeClipboard` by default (CB.0); tests
    /// grab the SAME handle `store_yank` / `read_register` consult.
    fn test_clipboard(editor: &Editor) -> lattice_core::ClipboardHandle {
        // `ServiceRegistry::get::<T>()` returns `Arc<T>`, so this is
        // `Arc<ClipboardHandle>` = `Arc<Arc<dyn Clipboard>>`; deref-clone the
        // inner handle so callers hold the plain `ClipboardHandle`.
        (*editor
            .services
            .get::<lattice_core::ClipboardHandle>()
            .expect("Editor::boot registers a default ClipboardHandle (CB.0)"))
        .clone()
    }

    #[test]
    fn clipboard_default_true_yank_mirrors_to_system_clipboard() {
        let document = lattice_core::Document::from_text("hello world\n");
        let mut editor = Editor::boot(document);
        let clipboard = test_clipboard(&editor);
        assert_eq!(clipboard.read(), None, "clipboard starts empty");
        let mut out = DispatchOutcome::default();
        editor.execute_ex_line("operator:yank motion:word-forward", &mut out);
        assert_eq!(
            clipboard.read(),
            Some("hello ".to_string()),
            "clipboard=true (default): an explicit yank mirrors to the system clipboard"
        );
    }

    #[test]
    fn clipboard_yank_only_rule_delete_and_change_do_not_mirror() {
        // The whole point of the boolean-yank-only design (vs vim's
        // `unnamedplus`): incidental delete/change must NOT clobber the
        // system clipboard.
        let document = lattice_core::Document::from_text("hello world\n");
        let mut editor = Editor::boot(document);
        let clipboard = test_clipboard(&editor);
        let mut out = DispatchOutcome::default();
        editor.execute_ex_line("operator:delete motion:word-forward", &mut out);
        assert_eq!(
            clipboard.read(),
            None,
            "delete must not mirror to the clipboard even though it populates registers"
        );
        let document2 = lattice_core::Document::from_text("hello world\n");
        let mut editor2 = Editor::boot(document2);
        let clipboard2 = test_clipboard(&editor2);
        let mut out2 = DispatchOutcome::default();
        editor2.execute_ex_line("operator:change motion:word-forward", &mut out2);
        assert_eq!(
            clipboard2.read(),
            None,
            "change must not mirror to the clipboard either"
        );
    }

    #[test]
    fn clipboard_false_opts_out_of_yank_mirroring() {
        let document = lattice_core::Document::from_text("hello world\n");
        let mut editor = Editor::boot(document);
        editor
            .config
            .parse_and_set_command("clipboard=false")
            .expect("clipboard is a registered bool option");
        let clipboard = test_clipboard(&editor);
        let mut out = DispatchOutcome::default();
        editor.execute_ex_line("operator:yank motion:word-forward", &mut out);
        assert_eq!(
            clipboard.read(),
            None,
            "clipboard=false: even an explicit yank stays register-only"
        );
        // Unnamed register still got it (registers are always populated).
        assert_eq!(
            editor.read_register(None).map(|r| r.content),
            Some("hello ".to_string())
        );
    }

    #[test]
    fn system_register_always_mirrors_regardless_of_clipboard_option() {
        // `"+y` / `"+p` are the explicit manual clipboard path and must work
        // even with `clipboard=false`.
        let document = lattice_core::Document::from_text("hello world\n");
        let mut editor = Editor::boot(document);
        editor
            .config
            .parse_and_set_command("clipboard=false")
            .expect("clipboard is a registered bool option");
        let clipboard = test_clipboard(&editor);
        editor.pending_register = Some(lattice_grammar::register::Register::System);
        let mut out = DispatchOutcome::default();
        editor.execute_ex_line("operator:yank motion:word-forward", &mut out);
        assert_eq!(
            clipboard.read(),
            Some("hello ".to_string()),
            "\"+y always reaches the system clipboard, independent of the `clipboard` option"
        );
    }

    #[test]
    fn paste_reads_live_clipboard_over_stale_internal_register() {
        // Simulates: user copied text in ANOTHER app (the clipboard has
        // content lattice never yanked). Under clipboard=true, paste must
        // read the live clipboard, not just the internal register.
        let document = lattice_core::Document::from_text("start\n");
        let editor = Editor::boot(document);
        let clipboard = test_clipboard(&editor);
        clipboard.write("from-another-app".to_string());
        let reg = editor
            .read_register(None)
            .expect("clipboard=true default: unnamed read falls through to the clipboard");
        assert_eq!(reg.content, "from-another-app");
    }

    #[test]
    fn paste_falls_back_to_register_when_clipboard_empty() {
        let document = lattice_core::Document::from_text("hello world\n");
        let mut editor = Editor::boot(document);
        let mut out = DispatchOutcome::default();
        // Yank first (populates both the register and, under clipboard=true,
        // the fake clipboard) ...
        editor.execute_ex_line("operator:yank motion:word-forward", &mut out);
        // ... then simulate the backend going empty (e.g. another app
        // cleared it) — read_register must still recover the in-memory copy.
        let clipboard = test_clipboard(&editor);
        assert!(clipboard.read().is_some());
        // FakeClipboard has no "clear" API surface beyond overwrite; write
        // an empty backend state indirectly isn't representable, so instead
        // assert the register-population invariant that backs the fallback:
        // the in-memory unnamed register is populated independent of the
        // clipboard mirror succeeding.
        assert_eq!(
            editor.unnamed_register.as_ref().map(|r| r.content.as_str()),
            Some("hello ")
        );
    }

    #[test]
    fn clipboard_false_read_register_ignores_clipboard_even_if_populated() {
        let document = lattice_core::Document::from_text("start\n");
        let editor = Editor::boot(document);
        editor
            .config
            .parse_and_set_command("clipboard=false")
            .expect("clipboard is a registered bool option");
        let clipboard = test_clipboard(&editor);
        clipboard.write("external".to_string());
        // Internal unnamed register is empty (nothing yanked yet); with
        // clipboard=false the read must NOT fall through to the clipboard.
        assert!(editor.read_register(None).is_none());
    }

    // ---- CB.3: terminal paste payload (docs/dev/architecture/clipboard.md §6) ----
    //
    // `terminal_paste_payload` is the one piece of CB.3 testable without a
    // real PTY (this codebase's established boundary: `lattice-terminal`'s
    // own real-process-spawning modules -- `buffer.rs` / `handle.rs` /
    // `spawner.rs` -- carry zero unit tests; only the pure VT-state-machine
    // logic, exercised via `SharedTerm::fixture`, is unit-tested). The
    // `SharedTerm::bracketed_paste` accessor has its own fixture-based test
    // in `lattice-terminal::reader`.

    #[test]
    fn terminal_paste_payload_wraps_when_bracketed() {
        assert_eq!(
            terminal_paste_payload("hello", true),
            b"\x1b[200~hello\x1b[201~".to_vec()
        );
    }

    #[test]
    fn terminal_paste_payload_passes_through_when_not_bracketed() {
        assert_eq!(terminal_paste_payload("hello", false), b"hello".to_vec());
    }

    // ---- CB.3 follow-up: `do_paste_text` (external/OS bracketed paste) routing ----
    //
    // `do_paste_text` fires from `Action::PasteText` — an OS/terminal-emulator
    // bracketed paste arriving at lattice, distinct from vim `p`/`P`. The two
    // sides of its terminal branch are testable without a real PTY: the
    // `Command`/`Search` guard (must NOT leak into the PTY) is fully
    // inspectable via `command_line`, and the positive route degrades to a
    // silent no-op with no terminal buffer registered (`do_terminal_input`'s
    // documented `None` path) — so we assert it does NOT splice into the
    // document, which pins that it took the terminal branch rather than the
    // `_ =>` document-insert arm. The actual PTY write stays unasserted,
    // matching CB.3's real-PTY testing boundary above.

    #[test]
    fn paste_text_into_command_line_while_terminal_focused_edits_command_line_not_pty() {
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::empty());
        editor.active_buffer = BufferKind::Terminal;
        editor.modal = ModalState::Command;
        editor.set_command_line_text(":e ");

        editor.do_paste_text("some/path");

        // The bracketed paste edits the `:` command line, it must not be
        // routed to the PTY just because a terminal buffer is focused.
        assert_eq!(editor.command_line(), ":e some/path");
    }

    #[test]
    fn paste_text_in_terminal_normal_mode_routes_to_pty_not_document() {
        let mut editor = crate::editor::Editor::boot(lattice_core::Document::from_text("abc\n"));
        editor.active_buffer = BufferKind::Terminal;
        editor.modal = ModalState::Normal;

        editor.do_paste_text("payload");

        // Terminal + non-Command/Search took the PTY branch; with no PTY
        // registered `do_terminal_input` no-ops, so the document must be
        // untouched (proving it did NOT hit the document-insert arm).
        assert_eq!(editor.document.text(), "abc\n");
        assert!(editor.command_line().is_empty());
    }

    #[test]
    fn visual_narrow_narrows_the_selection_end_to_end() {
        use lattice_protocol::position::Position;
        use lattice_protocol::selection::{Selection, SelectionSet, VisualMode};
        // The user's reported scenario: select lines in Visual, then
        // `:narrow`. Before the Visual `:` binding this was impossible
        // (`:` was unbound in Visual).
        let document = lattice_core::Document::from_text("L0\nL1\nL2\nL3\nL4\n");
        let mut editor = Editor::boot(document);
        editor.modal = ModalState::Visual(lattice_grammar::VisualKind::Linewise);
        editor.visual_anchor = Some(Position::new(1, 0));
        editor.cursor = Position::new(2, 0);
        editor.set_selections_blocking(SelectionSet::single(Selection {
            anchor: Position::new(1, 0),
            head: Position::new(2, 0),
            visual: Some(VisualMode::Linewise),
        }));
        // `:` (prefills `'<,'>` + captures the selection) then `narrow`.
        // MB.1: the `:` line is a buffer-backed surface — append through
        // the buffer and submit through the real path (which restores the
        // prior document before dispatching, so narrow runs on the doc).
        let _ = editor.dispatch(Action::EnterCommandLine);
        assert!(editor.command_line_active(), "`:` opens the command line");
        assert_eq!(
            editor.command_line(),
            "'<,'>",
            "Visual `:` prefills the range"
        );
        editor.set_command_line_text("'<,'>narrow");
        let _ = editor.dispatch(Action::CommandLineSubmit);
        assert!(
            !editor.command_line_active(),
            "submit restores the prior editing buffer"
        );
        let msg = editor.last_message.as_ref().expect("narrow echo present");
        assert!(
            msg.text.contains("narrowed to L2"),
            "`:'<,'>narrow` should narrow the selected lines (L2–3), got: {:?}",
            msg.text
        );
    }

    // ---- MB.1 (rich minibuffer, tier 1): buffer-backed `:` line ----

    /// Type `s` into the focused `*command-line*` buffer through the real
    /// Insert dispatcher (proving the universal readline grammar edits it).
    fn cl_type(editor: &mut Editor, s: &str) {
        let mut p = Vec::new();
        for c in s.chars() {
            editor.dispatch_chord(crate::chord::KeyChord::char(c), &mut p);
        }
    }

    fn cl_chord(editor: &mut Editor, chord: crate::chord::KeyChord) {
        let mut p = Vec::new();
        editor.dispatch_chord(chord, &mut p);
    }

    #[test]
    fn command_line_opens_as_focused_buffer_and_pane_keeps_its_buffer() {
        // The audit invariant: while `:` is open `self.document` is the
        // synthetic cmdline buffer, but the active pane still reports the
        // prior buffer (it renders its own, not `self.document`).
        let mut editor = Editor::boot(lattice_core::Document::from_text("hello\nworld\n"));
        let prior_doc = editor.document_buffer_id;
        let prior_pane = editor.active_pane_buffer_id();
        assert_eq!(
            prior_doc, prior_pane,
            "precondition: document == active pane"
        );
        editor.dispatch(Action::EnterCommandLine);
        assert!(editor.command_line_active(), "`:` opens the command line");
        assert_ne!(
            editor.document_buffer_id, prior_doc,
            "self.document swapped to the *command-line* buffer"
        );
        assert_eq!(
            editor.active_pane_buffer_id(),
            prior_pane,
            "the active pane keeps its own buffer while `:` is open"
        );
    }

    #[test]
    fn command_line_readline_cursor_move_and_mid_line_insert() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("x\n"));
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "dit foo");
        assert_eq!(editor.command_line(), "dit foo");
        assert_eq!(editor.cursor.byte, 7, "cursor at end after typing");
        // <C-a> to line start, then insert 'e' -> "edit foo".
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('a'));
        assert_eq!(editor.cursor.byte, 0, "<C-a> moves to line start");
        cl_type(&mut editor, "e");
        assert_eq!(
            editor.command_line(),
            "edit foo",
            "mid-line insert lands at cursor"
        );
        // <C-a> then <C-f> moves one byte right.
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('a'));
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('f'));
        assert_eq!(editor.cursor.byte, 1, "<C-f> moves one right");
    }

    #[test]
    fn command_line_ctrl_w_deletes_word_and_ctrl_u_kills_to_start() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("x\n"));
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "edit foo bar");
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('w'));
        assert_eq!(
            editor.command_line(),
            "edit foo ",
            "<C-w> deletes a word backward"
        );
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('u'));
        assert_eq!(editor.command_line(), "", "<C-u> kills to line start");
    }

    #[test]
    fn command_line_esc_cancels_and_restores_document_cursor_modal() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("hello\nworld\n"));
        editor.cursor = lattice_protocol::position::Position::new(1, 2);
        let prior_doc = editor.document_buffer_id;
        let prior_cursor = editor.cursor;
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "edit foo");
        cl_chord(
            &mut editor,
            crate::chord::KeyChord::special(crate::chord::SpecialKey::Esc),
        );
        assert!(
            !editor.command_line_active(),
            "<Esc> cancels the command line"
        );
        assert_eq!(editor.document_buffer_id, prior_doc, "document restored");
        assert_eq!(editor.cursor, prior_cursor, "cursor restored");
        assert!(matches!(editor.modal, ModalState::Normal), "modal restored");
        assert!(
            editor.command_history.is_empty(),
            "cancel dispatches nothing and pushes no history"
        );
    }

    #[test]
    fn command_line_ctrl_c_cancels_and_restores() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("hello\n"));
        let prior_doc = editor.document_buffer_id;
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "edit foo");
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('c'));
        assert!(!editor.command_line_active(), "<C-c> cancels");
        assert_eq!(editor.document_buffer_id, prior_doc, "document restored");
        assert!(
            editor.command_history.is_empty(),
            "no history push on cancel"
        );
    }

    #[test]
    fn command_line_cr_submits_and_pushes_history() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("hello\n"));
        let prior_doc = editor.document_buffer_id;
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "set number");
        cl_chord(
            &mut editor,
            crate::chord::KeyChord::special(crate::chord::SpecialKey::Enter),
        );
        assert!(
            !editor.command_line_active(),
            "<CR> submits + closes the line"
        );
        assert_eq!(
            editor.document_buffer_id, prior_doc,
            "document restored on submit"
        );
        assert_eq!(
            editor.command_history.last().map(String::as_str),
            Some("set number"),
            "submit pushes the line to history"
        );
    }

    #[test]
    fn command_line_history_walk_restores_pending_text() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("hello\n"));
        for cmd in ["set number", "set wrap"] {
            editor.dispatch(Action::EnterCommandLine);
            cl_type(&mut editor, cmd);
            cl_chord(
                &mut editor,
                crate::chord::KeyChord::special(crate::chord::SpecialKey::Enter),
            );
        }
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "xy");
        // <C-p> walks back to the newest, then older; <C-n> walks forward.
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('p'));
        assert_eq!(editor.command_line(), "set wrap");
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('p'));
        assert_eq!(editor.command_line(), "set number");
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('n'));
        assert_eq!(editor.command_line(), "set wrap");
        // Past the newest, the in-progress typed text returns.
        cl_chord(&mut editor, crate::chord::KeyChord::ctrl('n'));
        assert_eq!(
            editor.command_line(),
            "xy",
            "history walk restores pending text"
        );
    }

    #[test]
    fn command_line_completion_opens_and_accepts_on_the_buffer() {
        let mut editor = Editor::boot(lattice_core::Document::from_text("hello\n"));
        editor.dispatch(Action::EnterCommandLine);
        cl_type(&mut editor, "ed");
        // <Tab> opens the completion popup (mode-owned chord).
        cl_chord(
            &mut editor,
            crate::chord::KeyChord::special(crate::chord::SpecialKey::Tab),
        );
        let opened = editor.completion_state.is_some();
        assert!(opened, "<Tab> opens the cmdline completion popup");
        // <CR> while the popup is open accepts the candidate into the
        // buffer (does NOT submit) — two-stage accept.
        cl_chord(
            &mut editor,
            crate::chord::KeyChord::special(crate::chord::SpecialKey::Enter),
        );
        assert!(
            editor.command_line_active(),
            "accept keeps the command line open (submit is the next <CR>)"
        );
        assert!(
            editor.command_line().starts_with("ed"),
            "the accepted candidate is spliced into the buffer, got {:?}",
            editor.command_line()
        );
    }

