    /// PU.5c: the ephemeral completion-docs buffer lifecycle, reconciled
    /// once per cycle from `run_tick_pending`. Created (help-flavoured,
    /// ephemeral, invisible to `:ls`/`:bn`/`:bp`) when the focused candidate
    /// resolves a doc body; text-replaced in place when the body changes;
    /// garbage-collected when completion closes.
    #[test]
    fn completion_docs_reconcile_creates_ephemeral_buffer_and_gcs() {
        use lattice_completion::{CompletionTrigger, DocPopupState, InsertCompletionState};
        use lattice_protocol::position::Position;
        let mut e = Editor::boot(lattice_core::Document::empty());
        // No completion → no docs buffer.
        e.reconcile_completion_docs_buffer();
        assert!(e.completion_docs_buffer.is_none());

        // Completion open with a resolved doc body → ephemeral buffer.
        let mut st = InsertCompletionState::open(
            CompletionTrigger::Manual,
            Position::ZERO,
            Position::ZERO,
            String::new(),
        );
        st.doc_popup = Some(DocPopupState {
            for_index: 0,
            body: Some("# Docs\nbody".to_string()),
            scroll: 0,
        });
        e.insert_completion = Some(st);
        e.reconcile_completion_docs_buffer();
        let id = e
            .completion_docs_buffer
            .expect("ephemeral docs buffer created");
        assert!(e.buffers.contains_help(id), "docs buffer is help-flavoured");
        assert!(
            e.buffers.flags_of(id).expect("flags").ephemeral,
            "docs buffer carries the ephemeral flag"
        );
        assert!(
            !e.buffers.listed_ids_sorted().contains(&id),
            "ephemeral docs buffer excluded from :bn/:bp"
        );

        // Body changed → same buffer id, text replaced in place.
        e.insert_completion
            .as_mut()
            .unwrap()
            .doc_popup
            .as_mut()
            .unwrap()
            .body = Some("changed body".to_string());
        e.reconcile_completion_docs_buffer();
        assert_eq!(
            e.completion_docs_buffer,
            Some(id),
            "buffer reused on body change (no churn)"
        );
        let text = e
            .buffers
            .document_handle(id)
            .unwrap()
            .snapshot()
            .buffer
            .as_string();
        assert!(text.contains("changed body"), "text replaced; got {text:?}");

        // Completion closes → buffer GC'd.
        e.insert_completion = None;
        e.reconcile_completion_docs_buffer();
        assert!(e.completion_docs_buffer.is_none());
        assert!(
            e.buffers.document_handle(id).is_none(),
            "ephemeral buffer removed from the registry on dismiss"
        );
    }

    /// Picker live-preview must NOT run the full `do_edit` open path
    /// (synchronous parse + LSP attach + a permanent registry buffer per
    /// candidate — the cause of the find-file freeze). `do_preview` loads a
    /// bounded slice into ONE reusable ephemeral buffer; `do_edit` is
    /// reserved for the final accept.
    /// Hover / signature (the floating popup via `open_floating_popup`)
    /// must activate the help-mode MINOR — same as `:help` — so its option
    /// overrides (`nonu`, `signcolumn=no`, `wrap`) apply. Regression guard
    /// for the user-reported bug: hover popups showed line numbers because
    /// `open_floating_popup` activated MarkdownMode but NOT help-mode.
    /// A binary file (NUL byte) previews as a clean placeholder, not garbage;
    /// control/escape bytes in a "text" file are stripped (keeping tab) so
    /// they can't corrupt the terminal or leave leftover characters.
    #[test]
    fn read_preview_text_handles_binary_and_control_chars() {
        let dir = std::env::temp_dir().join(format!("lattice-preview-bin-{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        let bin = dir.join("img.bin");
        let txt = dir.join("esc.txt");
        std::fs::write(&bin, [0x89u8, 0x50, 0x00, 0x4e, 0x47]).unwrap(); // NUL inside
        std::fs::write(&txt, b"a\x1b[31mb\tc\r\nd").unwrap(); // ESC + tab + CR
        assert_eq!(
            Editor::read_preview_text(&bin).as_deref(),
            Some("<binary file — no preview>"),
            "binary file → placeholder, not garbage"
        );
        let cleaned = Editor::read_preview_text(&txt).expect("text read");
        assert!(!cleaned.contains('\u{1b}'), "ESC stripped");
        assert!(!cleaned.contains('\r'), "CR stripped");
        assert!(cleaned.contains('\t'), "tab kept");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// End-to-end: a file preview renders syntax-highlighted spans. Guards
    /// the user-reported "no highlighting during preview" — `do_preview`
    /// installs a fresh `Document` + sync-parsed `self.syntax` (mirroring the
    /// proven `do_edit` open path) so the cells worker's `DisplayMatrix`
    /// carries styled runs, instead of the prior reuse-buffer path where the
    /// syntax never reached the rendered matrix.
    #[test]
    fn preview_renders_syntax_highlighting() {
        let dir = std::env::temp_dir().join(format!("lattice-preview-hl-{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        let txt = dir.join("plain.txt");
        let md = dir.join("doc.md");
        std::fs::write(&txt, "just text\n").unwrap();
        std::fs::write(&md, "# heading\nbody\n").unwrap();
        let _ = txt; // (switch is structurally safe now — fresh buffer per preview)
        let mut e = Editor::boot(lattice_core::Document::empty());
        let _ = e.do_preview(md, None);
        e.publish_render_state();
        let pid = e.preview_buffer.expect("preview slot");
        // Drive the cells worker for the preview pane (async in production) and
        // assert the rendered DisplayMatrix carries syntax-highlighted spans —
        // the end-to-end check the handle-attached assertion missed.
        let cells = e.render_state.load_full().cells.load_full();
        let pane = cells
            .panes
            .iter()
            .find(|p| p.buffer_id == pid)
            .expect("preview pane present in cells inputs");
        let ct = crate::cells_worker::CellTheme {
            resolved: &cells.resolved_theme,
            ids: &cells.theme_ids,
        };
        let _ = crate::cells_worker::recompute_pane(pane, ct, &cells.whitespace);
        let dm = pane.display_matrix.load_full();
        let has_styled = (0..6u32).any(|line| {
            dm.row_at_source_line(line)
                .map(|r| {
                    r.runs
                        .iter()
                        .any(|run| run.style != lattice_syntax::Style::Default)
                })
                .unwrap_or(false)
        });
        assert!(
            has_styled,
            "preview must render syntax-highlighted (non-Default) spans"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// `:describe-key` arms a `Chord` arg slot; the host must PUBLISH
    /// `chord_capture` so the actor-based GPUI peer (which has no live
    /// `&Editor` at dispatch) can route the next keystroke into
    /// `translate_command_chord_capture` instead of dispatching it. Guards
    /// the GPUI "describe-key doesn't capture keys" bug.
    #[test]
    fn describe_key_prompt_publishes_chord_capture() {
        let mut e = Editor::boot(lattice_core::Document::from_text("x\n"));
        // Not armed → no capture.
        e.publish_render_state();
        assert!(
            !e.render_state
                .load_full()
                .active_document
                .load()
                .chord_capture,
            "no chord capture when the cmdline isn't at a Chord arg slot"
        );
        // Arm the describe-key prompt: Command mode at the Chord arg slot.
        e.modal = lattice_grammar::ModalState::Command;
        e.set_command_line_text("describe-key ");
        assert!(
            e.chord_capture_active(),
            "predicate true at the describe-key Chord arg slot"
        );
        e.publish_render_state();
        assert!(
            e.render_state
                .load_full()
                .active_document
                .load()
                .chord_capture,
            "publish must mirror chord_capture_active() into ad.chord_capture"
        );
    }

